insert into public.tree_planting_specs (slug,scientific_name,common_name_de,common_name_fr,common_name_it,common_name_en,common_name_es,category,mature_height_m_min,mature_height_m_max,mature_width_m_min,mature_width_m_max,growth_rate,years_to_mature,crown_form,deciduous_evergreen,root_type,root_depth_m,root_spread_factor,root_risk,light_need,soil_ph_min,soil_ph_max,soil_types,water_need,hardiness_zone,frost_tolerance_c,wind_tolerance,altitude_max_m,best_planting_months,planting_hole_width_factor,planting_hole_depth_factor,needs_stake,stake_count,needs_browse_protection,min_distance_to_building_m,min_distance_to_neighbor_m,hedge_spacing_m,height_class,toxicity,toxic_parts,allergen_potential,child_pet_safe,needs_pollination_partner,pollination_partners,self_fertile,pruning_window,care_notes,common_pests,swiss_notes,source) values
('abies_alba','Abies alba','Weisstanne (Edeltanne)','Sapin blanc','Abete bianco','Silver fir','Abeto blanco','nadelbaum','30','45','5','9','mittel','50','kegelförmig, im Alter storchennestartig abgeflacht','immergruen','herzwurzler','1.6',NULL,'mittel','halbschattig, jung schattenertragend','4.5','7','{lehmig,tiefgründig,frisch,tonig}','mittel bis hoch','4-7','-30',NULL,'1800','{3,4,9,10}','2.0','1.5','t','1','t','8','5',NULL,'forst','keine',NULL,'gering','t','f',NULL,'t','selten nötig; ggf. Spätsommer','Tiefer wurzelnd und sturmfester als Fichte (Herzwurzler), schattentolerant in der Jugend. Stark verbissgefährdet durch Reh/Gämse – Schutz nötig.','{Tannentrieblaus,Weisstannenrüssler,"Borkenkäfer (selten)",Mistel}','Wichtige Mischwaldbaumart, klimaresilienter als Fichte dank Pfahl-/Herzwurzel. Verbiss durch Schalenwild ist Hauptproblem der Naturverjüngung.','BAFU Waldbäume CH; tox.ch (ungiftig); Flora Helvetica'),
('acer_campestre','Acer campestre','Feldahorn (Massholder)','Érable champêtre','Acero campestre','Field maple','Arce menor','hecke','1.5','4','0.8','2.5','mittel','6','dicht buschig, als Baum rundlich','laubabwerfend','herzwurzler','1.2',NULL,'mittel','Sonne bis Halbschatten','5.5','8','{lehmig,tonig,kalkhaltig,humos}','mittel','5a-8b','-29',NULL,'1200','{3,4,10,11}','2.0','1.5','f','0','f','2','1','0.4','hoch','keine',NULL,'gering (insektenbestäubt)','t','f',NULL,'t','Juni-Juli und Februar (nicht im Saftfluss Frühjahr — blutet)','Einheimisch, ökologisch wertvoll (Bienenweide, Vogelnahrung). Ungiftig. Sehr schnittverträglich, ideal für naturnahe Schnitthecke. Hinweis: Blätter von Bergahorn (A. pseudoplatanus) sind für Pferde problematisch — Feldahorn gilt als unkritisch, ungiftig für Mensch/Haustier.','{"Ahorn-Runzelschorf (rein optisch)",Blattläuse,Mehltau}','Einheimisch im Mittelland und Jura, beliebte Wildhecken-/Niederheckenart, fördert Biodiversität.','BAFU einheimische Gehölze, Baumschul-Fachliteratur'),
('acer_palmatum','Acer palmatum','Japanischer Fächerahorn','Érable du Japon','Acero giapponese','Japanese maple','Arce japonés','zierbaum','3','6','2.5','5','langsam','15','malerisch-ausladend, schirmförmig bis aufrecht (sortenabhängig)','laubabwerfend','herzwurzler','0.7',NULL,'gering','halbschattig bis licht sonnig, vor Mittagssonne und Wind schützen','5','6.8','{humos,sandig-lehmig,durchlässig,frisch}','mittel','5b-8b','-24',NULL,'1000','{3,4,9,10}','2.0','1.5','f','0','f','2','2',NULL,'hoch','keine',NULL,'gering','t','f',NULL,'t','Spätsommer bis Frühherbst (Aug–Sept); NICHT im Frühjahr (starker Blutungsfluss/Saftdruck)','Hinweis: Acer-Arten (v.a. A. rubrum/Roter Ahorn) sind für Pferde toxisch (welke Blätter); A. palmatum gilt für Hunde/Katzen/Menschen als ungiftig. Empfindlich für Sonnenbrand und Trockenheit – mulchen, gleichmäßig feucht halten. Schnitt sparsam, Blutungsgefahr im Saftfluss.','{Verticillium-Welke,Sonnenbrand/Blattrandnekrosen,Blattläuse,Frosttrocknis}','In CH häufiger Solitär- und Kübelbaum; ungiftig für Mensch/Hund/Katze. Pferdehalter: generell keine Acer-Blätter verfüttern.','Baumschul-Fachliteratur, tox.ch (keine Listung für Mensch/Heimtier); bestätigt tox=keine, safe=true'),
('acer_platanoides','Acer platanoides','Spitzahorn','Érable plane','Acero riccio','Norway maple','Arce real','hausbaum','15','28','10','18','schnell','35','rundlich bis breit gewölbt','laubabwerfend','herzwurzler','2',NULL,'hoch','sonnig bis halbschattig','5.5','7.5','{lehmig,sandig-lehmig,frisch,durchlässig}','mittel','4b','-34',NULL,'1300','{3,4,10,11}','2.0','1.5','t','2','f','7','5',NULL,'forst','keine',NULL,'Pollen gering bis mäßig; auffällige gelbgrüne Frühjahrsblüte (insektenbestäubt)','t','f',NULL,'t','Sommer oder Herbst nach Laubfall; NICHT im Frühjahr (starker Saftfluss/Blutung)','Von tox.ch / Fachquellen als ungiftig für Mensch und Tier eingestuft (anders als der nah verwandte Bergahorn — keine relevante Hypoglycin-A-Weidemyopathie dokumentiert). Frühe wichtige Bienenweide. Starker, flach streichender Wurzeldruck — kann Beläge anheben, Mindestabstand einhalten. Sät sich stark aus.','{"Teerfleckenkrankheit (Rhytisma acerinum)",Mehltau,Verticillium-Welke}','In der Schweiz verbreiteter Stadt- und Parkbaum bis ~1300 m. Wurzeldruck bei Wegen/Belägen beachten. Ungiftig — kindersicher.','WebSearch tox/Fachquellen (gartenjournal, picturethis — Acer platanoides ungiftig), info flora CH; korrigiert von leicht/safe=false → keine/safe=true'),
('acer_pseudoplatanus','Acer pseudoplatanus','Bergahorn','Érable sycomore','Acero di monte','Sycamore maple','Arce blanco','hausbaum','20','35','12','20','schnell','40','breit gewölbt, dicht','laubabwerfend','herzwurzler','2.5',NULL,'hoch','halbschattig bis sonnig','5.5','7.5','{lehmig,frisch,nährstoffreich,tiefgründig}','mittel','4b','-34',NULL,'1700','{3,4,10,11}','2.0','1.5','t','2','t','8','6',NULL,'forst','stark','Samen und Keimlinge (Hypoglycin A); Blätter weitgehend ungiftig','Pollen gering bis mäßig (insektenbestäubt)','f','f',NULL,'t','Sommer (Juli/August) oder Herbst nach Laubfall; NICHT im Frühjahr (Blutungsdruck/Saftfluss)','Samen und Keimlinge enthalten Hypoglycin A — verursacht bei Pferden die tödliche Atypische Weidemyopathie. NICHT in Pferdeweiden-Nähe pflanzen; abgefallene Samen können mehrere hundert Meter verweht werden. Schnellwüchsig, starker Wurzeldruck — Mindestabstand zu Gebäuden/Leitungen einhalten.','{"Teerfleckenkrankheit (Rhytisma acerinum)",Mehltau,Blattläuse}','In der Schweiz häufigste Ahorn-Art, bis 1700 m (Bergwälder). Achtung Pferdehaltung: Bergahorn-Samen = Hauptursache Atypische Weidemyopathie (76% der Fälle Okt-Dez). tox.ch / Tierklinik-Warnung beachten.','WebSearch Atypische Weidemyopathie/Hypoglycin A (vetline, Thieme Tiermedizin), tox.ch, info flora CH'),
('aesculus_hippocastanum','Aesculus hippocastanum','Gewöhnliche Rosskastanie','Marronnier commun','Ippocastano','Horse chestnut','Castaño de Indias','hausbaum','20','30','12','20','mittel','30','dicht, breit gewölbt, oval','laubabwerfend','herzwurzler','2',NULL,'mittel','sonnig bis halbschattig','5.5','7.5','{lehmig,frisch,nährstoffreich,tiefgründig}','mittel bis hoch','5b','-28',NULL,'1000','{3,4,10,11}','2.0','1.5','t','2','f','8','6',NULL,'forst','leicht','Samen (Kastanien), unreife Früchte, Schale und junge Triebe (Aescin/Aesculin)','Pollen gering (insektenbestäubt); Blüten gute Bienenweide','f','f',NULL,'t','Winter (laublos) oder Hochsommer; verträgt Rückschnitt mäßig','Korrektur: von ''stark'' auf ''leicht'' herabgestuft — tox.ch/CliniTox stufen die Rosskastanie als schwach/leicht giftig ein (Aescin, Aesculin). Bei Kindern können ~5 verschluckte Samen Erbrechen/Durchfall/Sehstörungen auslösen; für Hunde Erbrechen/Koliken. Nicht verzehren (Verwechslung mit Esskastanie Castanea sativa!). child_pet_safe bleibt false, da bei Verzehr symptomatisch giftig.','{"Rosskastanien-Miniermotte (Cameraria ohridella — Massenbefall in CH)","Blattbräune (Guignardia)",Pseudomonas-Bakterienkrankheit}','In der Schweiz typischer Park-, Allee- und Biergartenbaum. Massiv von der Miniermotte befallen. Verwechslungsgefahr Samen mit essbarer Edelkastanie — wichtige Sicherheitsinfo für die App. Giftnotruf CH 145.','WebSearch tox/CliniTox/tiermedizinportal (schwach/leicht giftig, Aescin/Aesculin, 5 Samen Kind), info flora CH; korrigiert stark→leicht'),
('amelanchier_lamarckii','Amelanchier lamarckii','Kupfer-Felsenbirne (Korinthenbaum)','Amélanchier de Lamarck','Pero corvino di Lamarck','Juneberry (serviceberry)','Guillomo de Lamarck','hausbaum','4','6','3','5','mittel','7','locker trichterförmig, mehrstämmig, malerisch','laubabwerfend','herzwurzler','1',NULL,'gering','sonnig bis halbschattig','5','7','{sandig-lehmig,humos,durchlässig,frisch,"leicht sauer"}','mittel','4-8','-28',NULL,'1200','{3,4,10,11}','2.0','1.5','t','1','f','2.5','2','1.5','hoch','keine',NULL,'gering','t','f',NULL,'t','nach der Blüte (Spätfrühling) oder im Winter, wenig Schnitt nötig','Mehrwert-Hausbaum: weiße Blüte im April, essbare blau-schwarze süße Beeren im Juni (rohkostbar, vogelbeliebt), leuchtende Herbstfärbung orange-rot. Anspruchslos, anpassungsfähig. Kleiner Garten geeignet. Beeren ungiftig und essbar.','{"Birnengitterrost (gelegentlich)","Feuerbrand (selten anfällig)",Wollläuse}','Beliebter, robuster Kleinbaum/Großstrauch für CH-Gärten bis ca. 1200 m. Vogelnährgehölz, sehr bienenfreundliche Frühblüte. Pflegeleichter Hausbaum für kleine Grundstücke.','tox.ch / Info Flora CH / Baumschul-Fachliteratur'),
('aronia_melanocarpa','Aronia melanocarpa','Aronia (Schwarze Apfelbeere)','Aronie à fruits noirs','Aronia nera','Black chokeberry','Aronia negra','beerenstrauch','1.5','2.5','1.5','2.5','mittel','3','aufrecht buschig, dicht, mehrtriebig','laubabwerfend','flachwurzler','0.6',NULL,'gering','sonnig bis halbschattig','5','7','{anspruchslos,lehmig,sandig,humos}','mittel','3-7','-32',NULL,'1500','{3,4,10,11}','2.0','1.5','f','0','f','1','1','1.5','mittel','leicht','Samen/Kerne enthalten Spuren von Amygdalin (cyanogenes Glykosid); Fruchtfleisch unbedenklich','gering','t','f',NULL,'t','Spätwinter (Verjüngungs-/Auslichtungsschnitt)','Sehr robust, frosthart und anspruchslos, auch als Wildgehölz/Hecke. Beeren roh herb-adstringierend, meist verarbeitet (Saft, Marmelade) – sehr anthocyanreich. Amygdalin in den Kernen zerfällt beim Erhitzen; toxikologisch nur bei extrem hohem Rohverzehr relevant (mehrere kg), daher als Speise sicher. Einstufung ''leicht'' konservativ wegen cyanogenem Glykosid im Samen.','{"weitgehend schädlingsresistent","gelegentlich Blattläuse","Vögel an den Früchten"}','In CH als pflegeleichter, sehr winterharter Beeren- und Vogelnährstrauch beliebt; bis ~1500 m. Fruchtfleisch für Kinder/Haustiere unbedenklich; in haushaltsüblichen Mengen keine Cyanid-Gefahr (Max-Rubner-Institut, gartenjournal.net). ''leicht'' = vorsichtige Einstufung wegen Amygdalin im Kern.','Max-Rubner-Institut / gartenjournal.net (Amygdalin im Samen, Verzehr sicher); Tox Info Suisse Lookalike-Differenzierung'),
('betula_pendula','Betula pendula','Hängebirke','Bouleau verruqueux','Betulla bianca','Silver birch','Abedul péndulo','hausbaum','15','25','6','12','schnell','25','locker, überhängend, schmal','laubabwerfend','flachwurzler','1',NULL,'hoch','sonnig (Pionier-Lichtbaumart)','4','7','{sandig,durchlässig,mager,"trocken bis frisch"}','gering bis mittel','3','-40',NULL,'2000','{3,4,10,11}','2.0','1.5','t','1','f','6','5',NULL,'forst','keine',NULL,'Pollen SEHR stark — eines der wichtigsten Frühjahrs-Allergene (Heuschnupfen)','t','f',NULL,'t','Sommer/Herbst (August-Oktober); NICHT im Frühjahr/Spätwinter (starkes Bluten)','Ungiftig, aber starker Pollenallergen — nicht ideal für Allergiker-Haushalte. Flachwurzler mit hohem Wasserbedarf: kann nahe Gebäuden/Leitungen Probleme machen und Beläge anheben. Schnellwüchsige, kurzlebige Pionierart. Frosthart bis -40 °C.','{Birkenrost,Birkenminiermotte,Blattläuse,Hallimasch}','Heimische Pionierart, bis ~2000 m (subalpin). In der Schweiz Hauptursache von Frühjahrs-Pollenallergie. Flachwurzler — Abstand zu Drainagen/Fundamenten beachten.','tox.ch (ungiftig), aha! Allergiezentrum Schweiz (Pollen), info flora CH'),
('carpinus_betulus','Carpinus betulus','Hainbuche (Weissbuche, Hagebuche)','Charme commun','Carpino bianco','European hornbeam','Carpe','hecke','1.5','4','0.6','2.5','mittel','6','dicht, gut schnittverträglich; als Baum kegelförmig','laubabwerfend','herzwurzler','1.2',NULL,'mittel','Sonne bis Schatten','5.5','8','{lehmig,tonig,humos,kalkhaltig}','mittel','4a-8b','-30',NULL,'1000','{3,4,10,11}','2.0','1.5','f','0','f','2','1','0.35','hoch','keine',NULL,'mittel (windbestäubt, Pollen Frühjahr)','t','f',NULL,'t','Juni-Juli und Februar','Klassische Schnitthecke, hält trockenes Laub im Winter (Wind-/Sichtschutz). Ungiftig. Sehr schnittverträglich, verträgt Rückschnitt ins alte Holz.','{Hainbuchenspinnmilbe,Blattläuse}','Einheimisch, in der ganzen Schweiz bis Bergstufe verbreitet. Beliebteste Laubhecke neben Buche.','BAFU einheimische Gehölze, Baumschul-Fachliteratur'),
('castanea_sativa','Castanea sativa','Edelkastanie (Marroni, Esskastanie)','Châtaignier','Castagno','Sweet chestnut','Castaño','obstbaum','20','30','12','20','mittel','20','breit gewölbt, mächtig','laubabwerfend','herzwurzler','2.5',NULL,'mittel','sonnig bis halbschattig','4.5','6.5','{sauer,sandig-lehmig,kalkfrei,durchlässig}','mittel','5b-8','-27',NULL,'1000','{3,4,10,11}','2.0','1.5','t','2','t','8','6',NULL,'forst','keine',NULL,'mittel (Pollen, Esskastanie selten Nahrungsmittelallergen)','t','t','{"Castanea sativa ''Marrone''","Castanea sativa ''Bouche de Bétizac''","Castanea sativa Sämling"}','f','Winter (Februar) bis frühes Frühjahr, vor dem Austrieb','Braucht kalkfreien, sauren, durchlässigen Boden – verträgt keine Staunässe und keinen Kalk. Fremdbefruchtung nötig (zweiter Klon/Sämling). Mächtiger Endbaum, großzügiger Standort. Esskastanie (Marroni) essbar nach Rösten/Kochen.','{"Kastaniengallwespe (Dryocosmus kuriphilus)","Kastanienrindenkrebs (Cryphonectria parasitica)","Tintenkrankheit (Phytophthora)"}','Charakterbaum des Tessins und der Südschweiz (Selve-Kastanienhaine). Im Wallis und am Genfersee verbreitet. Bevorzugt milde, kalkfreie Lagen bis ca. 1000 m. Marroni-Tradition.','tox.ch / BAFU / WSL Edelkastanien-Merkblatt'),
('catalpa_bignonioides_nana','Catalpa bignonioides ''Nana''','Kugel-Trompetenbaum','Catalpa boule ''Nana''','Catalpa a palla ''Nana''','Dwarf Indian bean tree ''Nana''','Catalpa bola ''Nana''','zierbaum','4','6','3','5','mittel','15','dicht kugelig (veredelte Kugelform, blüht meist nicht)','laubabwerfend','herzwurzler','1',NULL,'mittel','sonnig bis halbschattig, windgeschützt (großes Laub windbruchgefährdet)','6','7.8','{lehm,sandig-lehmig,humos,nährstoffreich,frisch}','mittel bis hoch','5b-9a','-24',NULL,'800','{3,4,10,11}','2.0','1.5','t','1','f','3','2.5',NULL,'hoch','leicht','Wurzeln (PFAF: ''highly poisonous''), Früchte/Schoten und Samen (GI-/ZNS-Reizung bei größerer Menge); Laub kann Hautreizung auslösen','gering bis mittel (Kontakt-Hautreizung möglich)','f','f',NULL,'t','Winter bis zeitiges Frühjahr (laubfrei); Kugelkrone jährlich auf Astring zurücknehmen','Veredelte Kugelform ''Nana'' blüht in der Regel nicht und bildet kaum Schoten. Sehr großes Laub – windgeschützt stellen. Wurzeln und Schoten/Samen gelten als giftig (GI-/ZNS-Reizung), Laubkontakt kann Haut reizen. Jährlicher Rückschnitt für kompakte Kugel.','{Verticillium-Welke,Mehltau,"Wühlmausschäden an jungen Wurzeln"}','In CH beliebter Klein-/Vorgarten-Kugelbaum. KORRIGIERT/PRÄZISIERT: tox.ch und PFAF bestätigen Toxizität (Wurzeln stark, Schoten/Samen mäßig) – ''leicht'' beibehalten als konservative Untergrenze, child_pet_safe=false korrekt (NICHT auf true setzen).','PFAF (Wurzeln highly poisonous), Fachliteratur Catalpa-Schoten GI/ZNS Class II; bestätigt tox=leicht (konservativ), safe=false'),
('chamaecyparis_lawsoniana','Chamaecyparis lawsoniana','Lawsons Scheinzypresse (Gartenzypresse)','Cyprès de Lawson','Cipresso di Lawson','Lawson''s cypress (Port Orford cedar)','Ciprés de Lawson','nadelbaum','10','18','2','5','mittel','25','schmal kegelförmig bis säulenförmig mit überhängender Spitze','immergruen','flachwurzler','0.9',NULL,'mittel','sonnig bis halbschattig','5','7.5','{lehmig,frisch-feucht,humos,durchlässig}','mittel bis hoch','5-8','-25',NULL,'1000','{3,4,9,10}','2.0','1.5','f','0','f','2','0.6','0.6','hoch','stark','Alle Pflanzenteile (Laub, Triebe, ätherisches Öl) enthalten reizende Terpene (u. a. Thujen, Pinene). Verzehr schon kleiner Mengen kann Erbrechen, Durchfall, Fieber und Schwindel auslösen; Hautkontakt reizend.','Pollen stark allergen (Cupressaceae-Kreuzallergie); Schnittstaub hautreizend','f','f',NULL,'t','Frühjahr bis Spätsommer (nie ins alte, blattlose Holz schneiden)','KONSERVATIV als stark giftig eingestuft (Cupressaceae-Terpene wie bei Thuja, schwere Symptome schon bei kleinen Verzehrmengen, Fachquellen warnen explizit vor Pflanzung bei Kindern/Haustieren). Eingangsdaten ''leicht'' war inkonsistent mit safe=false – auf stark/child_pet_safe=false korrigiert. Flachwurzler, anfällig für Phytophthora-Wurzelfäule.','{"Phytophthora-Wurzelfäule (Hauptproblem)",Scheinzypressen-Miniermotte,"Borkenkäfer (Phloeosinus)",Spinnmilben}','Beliebte Hecken-/Solitärpflanze in Gärten; ökologisch arm und Phytophthora-anfällig. Naturnähere einheimische Alternativen bevorzugen.','tox.ch / Tox Info Suisse (Cupressaceae giftig); Gartenjournal/Garmundo (schwere Symptome, Kinder-/Haustier-Warnung); konservative Korrektur leicht→stark'),
('cornus_kousa_chinensis','Cornus kousa ''Chinensis''','Japanischer Blumen-Hartriegel','Cornouiller du Japon ''Chinensis''','Corniolo del Giappone ''Chinensis''','Chinese dogwood ''Chinensis''','Cornejo japonés ''Chinensis''','zierbaum','4','6','3','5','langsam','15','jung aufrecht-trichterförmig, später breit-rund mit waagerechten Etagenästen','laubabwerfend','herzwurzler','0.7',NULL,'gering','sonnig bis halbschattig, windgeschützt','5','6.8','{humos,sandig-lehmig,durchlässig,frisch}','mittel','5b-8b','-25',NULL,'900','{3,4,9,10}','2.0','1.5','t','1','f','2.5','2',NULL,'hoch','keine',NULL,'gering','t','f',NULL,'t','Schnitt selten nötig; falls nötig im Spätwinter/zeitigen Frühjahr (laubfrei)','Spät und lang blühend (cremeweiße Hochblätter), essbare himbeerartige rote Sammelfrüchte (ungiftig, leicht süß). Kalkmeidend – saurer, humoser Boden. Robuster und anthraknose-resistenter als Cornus florida. Flach wurzelnd – mulchen, nicht hacken.','{"meist sehr robust","Chlorose auf Kalkboden","selten Anthraknose (resistenter als C. florida)"}','In CH beliebter, robuster Solitär-Zierbaum; ungiftig, Früchte essbar – kinder-/haustiersicher. bestätigt tox=keine, safe=true.','Baumschul-Fachliteratur, tox.ch (keine Listung), essbare Frucht belegt; bestätigt tox=keine, safe=true'),
('cornus_mas','Cornus mas','Kornelkirsche (Tierlibaum)','Cornouiller mâle','Corniolo maschio','Cornelian cherry','Cornejo macho','wildgehoelz','4','6','3','5','langsam','20','dicht, rundlich bis breit, oft mehrstämmig','laubabwerfend','herzwurzler','1.5',NULL,'gering','sonnig bis halbschattig','6','8','{lehmig,kalkhaltig,humos,steinig}','mässig','5a','-29',NULL,'1200','{3,4,10,11}','2.0','1.5','t','1','t','2.5','1.5','1','hoch','keine',NULL,'gering (sehr frühe Pollenquelle Februar/März)','t','f',NULL,'t','nach der Fruchternte oder im Spätwinter; verträgt starken Schnitt','Sehr frühe Bienenweide (Februar/März, gelbe Blüten vor dem Laub). Essbare, vitaminreiche Früchte. Langsam wachsend, dafür sehr langlebig. Heckenfähig.','{"weitgehend robust","selten Cornus-Anthraknose"}','Heimisch (CH-Mittelland/Jura, wärmeliebend), wichtigste sehr frühe Insektennährpflanze. Essbare Früchte traditionell für Konfitüre.','tox.ch, InfoFlora, BAFU Wildgehölze, Baumschul-Fachliteratur'),
('cornus_sanguinea','Cornus sanguinea','Roter Hartriegel (Blutroter Hornstrauch)','Cornouiller sanguin','Sanguinello (corniolo sanguinello)','Common dogwood','Cornejo sanguíneo','wildgehoelz','2','4','2','4','mittel','10','aufrecht bis breit, dicht, Ausläufer bildend, rote Zweige','laubabwerfend','flachwurzler','1',NULL,'mittel','sonnig bis halbschattig','6','8','{lehmig,kalkhaltig,frisch,humos}','mässig','5a','-29',NULL,'1400','{3,4,10,11}','2.0','1.5','f','0','t','2','1.5','0.8','mittel','leicht','rohe schwarze Früchte schwach giftig/ungeniessbar (Cornin in Rinde, Blättern, Wurzeln); roher Verzehr kann Magen-Darm-Beschwerden auslösen','gering','t','f',NULL,'t','Spätwinter (auf den Stock setzen für leuchtend rote Winterzweige); Ausläufer entfernen','Bildet Wurzelausläufer - kann sich ausbreiten, bei kleinen Gärten beobachten. Rote Winterzweige dekorativ (Rückschnitt fördert Färbung). Vogelnährgehölz, gute Bienenweide. Früchte roh leicht giftig - nicht verzehren.','{Cornus-Anthraknose,Blattläuse,"Spinnmilben (bei Trockenheit)"}','Heimisch, häufiges Wildhecken-Gehölz im Mittelland/Jura. Achtung Ausläuferbildung an Grundstücksgrenzen.','tox.ch, InfoFlora, GIZ Bonn, BAFU Wildgehölze'),
('corylus_avellana','Corylus avellana','Haselnuss (Gemeine Hasel)','Noisetier commun','Nocciolo','Common hazel','Avellano','wildgehoelz','3','6','3','5','schnell','6','mehrstämmig, trichterförmig aufrecht','laubabwerfend','herzwurzler','1.2',NULL,'gering','sonnig bis halbschattig','5.5','7.5','{lehm,sandig-lehmig,humos,frisch,kalkhaltig}','mittel','4-8','-30',NULL,'1500','{3,4,10,11}','2.0','1.5','f','0','t','2','2','1.5','hoch','keine',NULL,'hoch (Haselpollen früher Frühblüher, starkes Allergen; Haselnuss starkes Nahrungsmittelallergen)','t','t','{"Corylus avellana ''Hallesche Riesennuss''","Corylus avellana ''Webbs Preisnuss''","Corylus maxima ''Rotblättrige Zellernuss''"}','f','Winter (nach der Ernte / vor dem Blühbeginn Januar-Februar)','Mehrstämmiger Strauch, gut als freie Hecke oder Solitär. Windbestäubt, Fremdbefruchtung erhöht Ertrag. Sehr anpassungsfähig, anspruchslos. Alle paar Jahre auslichten/auf-den-Stock setzen verjüngt. Pollen ist starker Frühblüher-Allergen.','{"Haselnussbohrer (Rüsselkäfer)",Haselnuss-Gallmilbe,Haselnuss-Mehltau}','Heimisches Wildgehölz in der ganzen CH bis 1500 m, häufig an Waldrändern und in Hecken. Wichtiges Vogel- und Bienennährgehölz (Frühblüher, Pollenquelle). Für Vernetzungshecken empfohlen.','tox.ch / Info Flora CH / BAFU Heckenmerkblatt'),
('crataegus_laevigata_paul_s_scarlet','Crataegus laevigata ''Paul''s Scarlet''','Rotdorn (Rotblühender Weissdorn)','Aubépine rouge ''Paul''s Scarlet''','Biancospino rosso ''Paul''s Scarlet''','Red hawthorn ''Paul''s Scarlet''','Espino albar rojo ''Paul''s Scarlet''','zierbaum','4','7','3','5','mittel','15','rundlich bis breit-eiförmig, dicht','laubabwerfend','herzwurzler','1.2',NULL,'gering','sonnig bis halbschattig','6','7.8','{lehm,kalkhaltig,sandig-lehmig,schwer}','gering bis mittel','5a-8a','-29',NULL,'1300','{3,4,10,11}','2.0','1.5','t','1','f','3','2',NULL,'hoch','keine',NULL,'gering bis mittel (Blütenduft kann empfindliche Personen reizen)','t','f',NULL,'t','nach der Blüte (Juni) bzw. im Winter (laubfrei)','Gefüllt blühende, sterile Zierform – setzt kaum/keine Früchte an. Bienen-/Insektengehölz. Dornen beachten. Crataegus ist ungiftig (sogar Heilpflanze – Herz/Kreislauf), Beeren der Wildform essbar. Achtung Feuerbrand-Wirtspflanze (in CH meldepflichtig).','{"Feuerbrand (Erwinia amylovora – meldepflichtig)",Weißdorn-Gespinstmotte,Mehltau,Rost}','In CH häufiger Stadt-/Alleebaum; UNGIFTIG (Heilpflanze). WICHTIG: Feuerbrand-Wirt – in CH meldepflichtig (EPSDV), in Befallszonen Pflanzbeschränkungen beachten.','Baumschul-Fachliteratur, tox.ch (keine Listung), BLW Feuerbrand; bestätigt tox=keine, safe=true'),
('crataegus_monogyna','Crataegus monogyna','Eingriffliger Weissdorn','Aubépine à un style','Biancospino comune','Common hawthorn','Espino albar','wildgehoelz','3','6','2','5','mittel','15','rundlich, dicht verzweigt, dornig','laubabwerfend','herzwurzler','1.5',NULL,'gering','sonnig bis halbschattig','6','8','{lehmig,kalkhaltig,sandig-lehmig}','mässig','5a','-34',NULL,'1500','{3,4,10,11}','2.0','1.5','f','0','t','2','1','0.8','hoch','keine',NULL,'mittel (Blütenduft kann empfindliche Personen reizen)','t','f',NULL,'t','Spätwinter (Februar) oder nach der Blüte; Heckenschnitt Juni','Sehr robust, hervorragendes Vogelnähr- und Nistgehölz. Dornen bieten Schutz für Brutvögel. Anfällig für Feuerbrand (meldepflichtig in CH).','{"Feuerbrand (Erwinia amylovora)",Mehltau,Weissdorngespinstmotte}','Heimisch, wichtigstes Wildhecken-Gehölz. Feuerbrand-Wirtspflanze - in einigen CH-Kantonen Pflanzbeschränkungen in Obstbaugebieten beachten.','tox.ch, InfoFlora, BAFU Wildgehölze, Baumschul-Fachliteratur'),
('cydonia_oblonga','Cydonia oblonga','Quitte','Cognassier','Cotogno','Quince','Membrillero','obstbaum','3','6','3','5','langsam','6','rundlich bis malerisch knorrig, oft mehrstämmig/strauchartig','laubabwerfend','flachwurzler','1',NULL,'gering','sonnig, warm','5.5','7.5','{lehmig,humos,feucht,naehrstoffreich}','mittel bis hoch','5-8','-25',NULL,'800','{3,4,10,11}','2.0','1.5','t','1','t','2','2',NULL,'hoch','leicht','Samen (Kerne) enthalten cyanogene Glykoside (Amygdalin) — Kerne nicht zerkauen; Fruchtfleisch nach Erhitzen essbar','gering (Rosaceae-Pollen)','t','f',NULL,'t','Winter (Februar-März); nur sparsam auslichten, trägt am vorjährigen Holz','Selbstfruchtbar, gut für Einzelbaum. Frucht roh hart/herb, erst gekocht genießbar (Gelee, Mus). Feuerbrand-anfällig. Kerne ganz schlucken unbedenklich, nicht zerkauen.','{Feuerbrand,"Quittenrost / Blattbräune (Diplocarpon)",Monilia,Blattläuse}','Robuste alte Hausgarten-Frucht, in wärmeren CH-Lagen verbreitet. Feuerbrand (Erwinia amylovora) meldepflichtig — als Rosaceae anfälliger Wirt.','tox.ch / CliniTox UZH / Baumschul-Fachliteratur'),
('euonymus_europaeus','Euonymus europaeus','Pfaffenhütchen (Gewöhnlicher Spindelstrauch)','Fusain d''Europe','Fusaggine comune','European spindle','Bonetero','wildgehoelz','2','4','1.5','3','mittel','12','aufrecht, locker, oft mehrstämmig','laubabwerfend','herzwurzler','1.2',NULL,'gering','halbschattig bis sonnig','6','8','{lehmig,kalkhaltig,frisch,humos}','mässig','4b','-34',NULL,'1200','{3,4,10,11}','2.0','1.5','f','0','t','2','1.5','1','mittel','stark','ALLE Pflanzenteile, besonders die leuchtend rosa-orangen Früchte/Samen (herzwirksame Glykoside, Alkaloide); bereits 3 Samen können bei Kindern schwere Vergiftung auslösen','gering','f','f',NULL,'t','Spätwinter oder nach der Blüte; bei Arbeiten Handschuhe tragen','WARNUNG: Eine der gefährlichsten heimischen Giftpflanzen, zählt zu den ''gefährlichen Vier'' (mit Goldregen, Stechpalme, Seidelbast). Leuchtende Früchte locken Kinder magnetisch an. NICHT in Gärten mit Kleinkindern/Haustieren pflanzen. Ökologisch wertvoll als Nährgehölz für Vögel (für sie ungiftig).','{"Pfaffenhütchen-Gespinstmotte (Yponomeuta cagnagella)",Blattläuse}','Heimisch, ökologisch wertvoll, aber STARK GIFTIG - tox.ch listet als gefährliche Giftpflanze. Bei Kindergärten/Spielplätzen vermeiden. Tox-Notruf CH: 145.','tox.ch (Giftpflanzen-Liste ''gefährliche Vier''), InfoFlora, BAFU'),
('fagus_sylvatica','Fagus sylvatica','Rotbuche','Hêtre commun','Faggio comune','European beech','Haya común','hecke','1.5','4','0.6','2.5','mittel','7','dicht, als Hecke kompakt; als Baum breit gewölbt','laubabwerfend','herzwurzler','1.5',NULL,'mittel','Sonne bis Halbschatten','4.5','7.5','{lehmig,humos,durchlässig,kalkhaltig}','mittel','4a-7b','-29',NULL,'1500','{3,4,10,11}','2.0','1.5','f','0','f','2','1','0.35','hoch','leicht','rohe Bucheckern (Fagin/Oxalsäure) in grösserer Menge','mittel (Pollen Frühjahr)','t','f',NULL,'t','Juni-Juli und Februar','Behält Winterlaub als Sichtschutz. Bucheckern roh in Menge leicht giftig (Magen-Darm), geröstet essbar — für normale Garten-/Heckennutzung unkritisch, daher child_pet_safe.','{Buchenwollschildlaus,Buchenspringrüssler,Mehltau}','Häufigster Laubbaum der Schweiz, einheimisch bis 1500m. Als Hecke wie Hainbuche, bevorzugt durchlässigere Böden.','BAFU, tox.ch (Bucheckern), Baumschul-Fachliteratur'),
('fragaria_x_ananassa','Fragaria x ananassa','Gartenerdbeere','Fraisier cultivé','Fragola coltivata','Garden strawberry','Fresón / fresa cultivada','beerenstrauch','0.15','0.3','0.2','0.4','schnell','1','niedrige Rosettenstaude, Ausläufer bildend (krautig, kein echter Strauch)','halbimmergruen','flachwurzler','0.3',NULL,'gering','sonnig','5.5','6.8','{humos,durchlässig,lehmig-sandig,nährstoffreich}','mittel bis hoch','4-8','-20',NULL,'1500','{7,8,9}','2.0','1.5','f','0','f','0.2','0.3',NULL,'niedrig','keine',NULL,'mittel (Birkenpollen-assoziierte Kreuzallergie möglich, Fruchtallergie)','t','f',NULL,'t','nach Ernte: Laub/Ausläufer einkürzen, alte Pflanzen nach 3 Jahren ersetzen','Botanisch krautige Staude, kein verholzender Strauch – Pflanzung im Spätsommer (Juli-Sept.) für Ernte im Folgejahr ideal. Bildet Ausläufer (Tochterpflanzen) zur Vermehrung. Mulchen mit Stroh hält Früchte sauber/trocken. Beet alle 3 Jahre erneuern (Ertragsrückgang, Bodenmüdigkeit).','{"Grauschimmel (Botrytis)",Erdbeerblütenstecher,Schnecken,Kirschessigfliege,"Wurzelfäule bei Staunässe"}','In CH die meistangebaute Garten-Beere, kinder- und haustiersicher. Birkenpollen-Allergiker können auf frische Erdbeeren reagieren (orales Allergiesyndrom) – daher allergen_potential ''mittel''. Bis ~1500 m.','Tox Info Suisse (tox.ch) – nicht giftig gelistet; Baumschul-/Gartenbau-Fachliteratur'),
('ilex_aquifolium','Ilex aquifolium','Gewöhnliche Stechpalme (Hülse, Christdorn)','Houx commun','Agrifoglio','European holly','Acebo común','hecke','2','5','1','3','langsam','10','dicht, kegelförmig bis säulig, stachelblättrig','immergruen','herzwurzler','0.8',NULL,'gering','Halbschatten bis Schatten','4.5','7','{humos,lehmig,durchlässig,frisch}','mittel','6a-9b','-20',NULL,'1200','{4,5,9,10}','2.0','1.5','f','0','f','1','0.6','0.5','hoch','stark','rote Beeren (v.a.), auch Blätter (Triterpene, Saponine, Theobromin, Ilicin)','gering','f','t','{"Ilex aquifolium (männl. Klon, z.B. ''Blue Prince'' / ''Heckenstar'')"}','f','Juni-Juli und Februar-März','Stark giftig: rote Beeren — ab ca. 4 Beeren Symptome, 20-30 Beeren potenziell tödlich bei Kindern (tox.ch/GIZ). Hochattraktiv für Kinder. Zweihäusig: nur weibliche Pflanzen tragen Beeren, männlicher Befruchter nötig. Einheimisch, geschützt.','{"Ilex-Miniermotte (Blattminierer)",Schildläuse,Blattläuse}','Einheimisch, in mehreren Kantonen geschützt (Pflücken/Ausgraben verboten). Stark giftige Beeren — kritisch bei Kleinkindern, Tox Info Suisse 145.','tox.ch, GIZ Bonn, vetpharm.uzh.ch (4 Beeren Symptome / 20-30 letal)'),
('juglans_regia','Juglans regia','Walnuss (Echte Walnuss, Baumnuss)','Noyer commun','Noce comune','Common walnut (English walnut)','Nogal común','obstbaum','15','25','12','18','mittel','15','breit rundlich, ausladend','laubabwerfend','pfahlwurzler','3',NULL,'hoch','sonnig','6','7.5','{lehm,sandig-lehmig,kalkhaltig,nährstoffreich}','mittel','6a-9','-25',NULL,'800','{3,4,10,11}','2.0','1.5','t','2','t','8','6',NULL,'forst','leicht','Grüne Fruchtschalen, Blätter und Wurzeln enthalten Juglon (allelopathisch, leicht reizend); für Pferde/Hunde sind verschimmelte Nüsse und das Kernholz problematisch (Hufrehe-Risiko beim Pferd)','mittel (Pollen, Nuss-Allergen ein starkes Nahrungsmittelallergen)','t','f','{"Juglans regia ''Geisenheim''","Juglans regia ''Franquette''","Juglans regia ''Mars''"}','t','Spätsommer (August), niemals im Frühjahr wegen starkem Bluten','Tiefgründiger, frischer Boden nötig. Juglon hemmt Unterpflanzung (Allelopathie) – kein Gemüsebeet darunter. Spätfrostgefährdet im Austrieb. Schnitt nur im Spätsommer, sonst starker Saftfluss. Großer Endbaum – Abstand zu Gebäuden wegen Pfahlwurzel und Kronenbreite einhalten.','{Walnussfruchtfliege,"Marssonina-Blattflecken (Walnuss-Anthraknose)","Bakterienbrand (Xanthomonas)"}','In der CH bis ca. 800 m verbreitet, traditioneller Hofbaum im Mittelland und in den Tälern. Liefert Baumnuss (Nidwaldner Bauernhofbaum). Spätfrost in Höhenlagen begrenzt Ertrag.','tox.ch / wildfind.com / pferde.world / Baumschul-Fachliteratur'),
('juniperus_communis','Juniperus communis','Gemeiner Wacholder','Genévrier commun','Ginepro comune','Common juniper','Enebro común','nadelbaum','1','6','1','3','langsam','20','säulenförmig bis breit-strauchig, sehr variabel','immergruen','herzwurzler','1.2',NULL,'gering','vollsonnig','4.5','8','{sandig,kalkhaltig,mager,trocken,steinig}','gering','2-7','-40',NULL,'2500','{4,5,9,10}','2.0','1.5','f','0','t','1.5','1','0.8','hoch','leicht','Nadeln und Beerenzapfen enthalten ätherische Öle (u. a. Terpinen-4-ol); in größeren Mengen nieren- und magenreizend. Reife Beeren in Küchenmengen genießbar (Gewürz), in Überdosis und in der Schwangerschaft zu meiden (uteruswirksam).','Pollen mäßig allergen (Frühjahr)','t','t','{"männlicher Juniperus communis in der Nähe (zweihäusig)"}','f','Frühjahr; nur Formschnitt, treibt aus altem Holz kaum aus','Nur leicht giftig – reife Beeren sind das bekannte Küchengewürz und für Kinder/Haustiere nicht gefährlich. Achtung Verwechslung mit dem STARK giftigen Sadebaum (Juniperus sabina). Hautreizung durch ätherische Öle möglich.','{Wacholder-Gespinstmotte,"Birnengitterrost (Wirtswechsel zu Birne)",Wacholderblattläuse}','Einheimisch, vom Tiefland bis ~2500 m ü. M.; geschützt, an Magerstandorten und Wacholderheiden. Birnengitterrost: nicht neben Birnbäumen pflanzen (Zwischenwirt).','tox.ch / Tox Info Suisse (leicht giftig); A.Vogel Pflanzenlexikon; Flora Helvetica'),
('laburnum_watereri_vossii','Laburnum × watereri ''Vossii''','Goldregen (Edel-Goldregen)','Cytise ''Vossii''','Maggiociondolo ''Vossii''','Golden chain tree ''Vossii''','Lluvia de oro ''Vossii''','zierbaum','4','6','3','5','mittel','12','aufrecht bis breit, trichterförmig, überhängende Blütentrauben','laubabwerfend','herzwurzler','1',NULL,'gering','sonnig bis halbschattig','6','7.8','{lehm,kalkhaltig,sandig-lehmig,durchlässig}','gering bis mittel','5b-8a','-26',NULL,'1000','{3,4,10,11}','2.0','1.5','t','1','f','3','2.5',NULL,'hoch','toedlich','ALLE Pflanzenteile, v.a. Samen und Hülsen (Cytisin); wenige Samen können für Kinder lebensbedrohlich sein','gering','f','f',NULL,'t','nach der Blüte (Juni/Juli); möglichst wenig schneiden, schlechte Wundheilung','WARNUNG: Hochgiftig (Cytisin) – eine der gefährlichsten Garten-Zierpflanzen. Erbsenähnliche Samen/Hülsen sind für Kinder besonders verlockend und potenziell tödlich. NICHT in Kinder-/Spielbereiche, Schulen, Kitas pflanzen. ''Vossii'' setzt weniger Samen an, ist aber dennoch giftig. Bei Verdacht sofort Tox-Zentrum 145 (CH) anrufen.','{"meist robust",Blattläuse,Goldregen-Miniermotte}','In CH verbreiteter Ziergehölz, aber tox.ch führt Goldregen als TÖDLICH giftig – häufige Vergiftungsmeldungen bei Kindern. child_pet_safe=false zwingend. Schweizer Tox-Notruf: 145.','tox.ch (Laburnum/Cytisin – tödlich), Baumschul-Fachliteratur; bestätigt tox=toedlich, safe=false'),
('larix_decidua','Larix decidua','Europäische Lärche','Mélèze d''Europe','Larice europeo','European larch','Alerce europeo','nadelbaum','25','40','4','8','schnell','40','schmal kegelförmig, locker, jung pyramidal','laubabwerfend','herzwurzler','1.8',NULL,'gering','vollsonnig (ausgeprägte Lichtbaumart)','4.5','7.5','{lehmig,kiesig,tiefgründig,durchlässig}','mittel','2-6','-40',NULL,'2500','{3,4,10,11}','2.0','1.5','t','1','t','6','4',NULL,'forst','keine',NULL,'gering','t','f',NULL,'t','selten nötig; Winter (laubfrei)','Einziger heimischer Nadelbaum, der im Winter die Nadeln abwirft (laubabwerfend). Tief- bis herzwurzelnd, sturmfest, geringes Gebäuderisiko. Braucht volle Sonne.','{Lärchenminiermotte,"Lärchenkrebs (Lachnellula)",Lärchenblasenfuß}','Hochlagen-/Gebirgsbaum, bis ~2500 m ü. M. (Engadin, Wallis). Klimaresilient in subalpiner Stufe; im Tiefland krankheitsanfälliger (Lärchenkrebs).','BAFU Waldbäume CH; tox.ch (ungiftig); Flora Helvetica'),
('ligustrum_ovalifolium','Ligustrum ovalifolium','Ovalblättriger Liguster (Rainweide)','Troène de Californie','Ligustro a foglie ovali','California privet','Aligustre de hoja oval','hecke','2','3.5','0.6','1.5','schnell','4','dicht aufrecht, schnittverträglich','halbimmergruen','herzwurzler','0.8',NULL,'gering','Sonne bis Halbschatten','5.5','7.8','{lehmig,sandig,humos,kalkhaltig}','mittel','6a-9b','-20',NULL,'1200','{3,4,9,10}','2.0','1.5','f','0','f','0.5','0.5','0.3','mittel','leicht','Beeren (schwarz), Blätter','mittel (Blütenduft, Pollen)','f','f',NULL,'t','Mai-September (2x jährlich für dichte Hecke)','Sehr schnittverträglich, ideale Formhecke. Beeren leicht giftig (Ligustrin/Syringin) — Erbrechen/Durchfall bei Kindern. Schnitt vor Blüte mindert Pollenflug.','{Ligusterschwärmer,Blattläuse,"Echter Mehltau"}','Weit verbreitete Schnitthecke im Mittelland. Bei Giftnotfall Tox Info Suisse 145.','tox.ch (Ligustrum), Baumschul-Fachliteratur'),
('ligustrum_vulgare','Ligustrum vulgare','Gewöhnlicher Liguster (Rainweide)','Troène commun','Ligustro comune','Common privet (wild privet)','Aligustre común','hecke','2','3.5','0.8','2','schnell','4','dicht aufrecht, buschig','halbimmergruen','herzwurzler','0.9',NULL,'gering','Sonne bis Halbschatten','6','8','{lehmig,kalkhaltig,humos,steinig}','mittel','4a-8b','-29',NULL,'1500','{3,4,10,11}','2.0','1.5','f','0','f','0.5','0.5','0.3','mittel','leicht','Beeren (schwarz) und Blätter (Ligustrin, Syringin)','mittel (Blütenduft, Pollen)','f','f',NULL,'t','Mai-September (mehrmals); ungeschnitten Blüten/Beeren für Wildtiere','Beeren leicht giftig — Erbrechen/Durchfall bei Kindern, problematisch für Hunde. Einheimisch, ökologisch wertvoll (Schmetterlinge, Vögel) wenn ungeschnitten. Sehr robust und kalkliebend.','{Ligusterschwärmer,Blattläuse,"Echter Mehltau",Thripse}','Einheimisch, Wildhecken-/Naturheckenart. Beeren leicht giftig — Tox Info Suisse 145.','tox.ch (Ligustrum-Beeren), BAFU einheimische Gehölze'),
('liquidambar_styraciflua','Liquidambar styraciflua','Amberbaum','Copalme d''Amérique','Liquidambar (Storace americano)','American sweetgum','Liquidámbar (Ocozol)','hausbaum','12','20','6','10','mittel','25','jung kegelförmig, später breit-eiförmig bis rundlich','laubabwerfend','herzwurzler','1.5',NULL,'mittel','sonnig','5','7','{humos,sandig-lehmig,lehm,"frisch bis feucht"}','mittel bis hoch','5b-9a','-26',NULL,'800','{3,4,10,11}','2.0','1.5','t','2','f','6','4',NULL,'forst','keine',NULL,'gering bis mittel (windbestäubt, mäßiger Pollenflug)','t','f',NULL,'t','Winter (laubfrei) bis zeitiges Frühjahr; Leitastaufbau jung erziehen','Großbaum mit spektakulärer Herbstfärbung (gelb-orange-purpur). Stachelige Fruchtkapseln können Stolper-/Rasenmäher-Hindernis sein – fruchtarme Sorten (''Worplesdon'') wählen. Kalkmeidend, leicht saurer, frischer Boden bevorzugt. Großer Endbaum – ausreichend Abstand.','{"meist robust","Chlorose auf Kalkböden","gelegentlich Wurzelfäule auf Staunässe"}','In CH zunehmend als klimafester Park-/Straßenbaum gepflanzt; ungiftig. Als Forst-/Großbaum ausreichend Gebäudeabstand (Endhöhe bis 20 m) – height_class=forst konsistent.','Baumschul-Fachliteratur, tox.ch (keine Listung); bestätigt tox=keine, safe=true, height_class=forst konsistent mit 20 m'),
('lonicera_caerulea_var_kamtschatica','Lonicera caerulea var. kamtschatica','Maibeere (Kamtschatka-Heckenkirsche, Honigbeere)','Camérisier (baie de mai, chèvrefeuille comestible)','Caprifoglio commestibile (bacca di maggio)','Honeyberry (haskap)','Camerisa (baya de miel)','beerenstrauch','1.2','1.8','1','1.5','mittel','3','buschig kompakt, dicht verzweigt','laubabwerfend','flachwurzler','0.5',NULL,'gering','sonnig bis halbschattig','5.5','7.5','{humos,lehmig,durchlässig,anspruchslos}','mittel','2-7','-40',NULL,'1800','{3,4,9,10,11}','2.0','1.5','f','0','f','1','0.8','1','niedrig','keine',NULL,'gering','t','t','{"Lonicera caerulea var. kamtschatica (andere Sorte, z. B. ''Wojtek'' × ''Aurora'')"}','f','nach der Ernte / Spätwinter (wenig Schnittbedarf)','WICHTIG: NUR die blaufrüchtige var. kamtschatica/edulis ist essbar – die heimischen rot-/schwarzfrüchtigen Heckenkirschen (L. xylosteum, L. nigra) sind giftig! Diese Sorte ist die essbare Ausnahme der Gattung. Sehr früh reifend (Mai/Juni), extrem frosthart. Fremdbefruchter: zwei verschiedene Sorten für Ertrag pflanzen.','{"weitgehend schädlingsresistent","Vögel an den frühen Früchten","selten Blattläuse"}','In CH als frühestes Beerenobst und extrem winterhart (bis -40 °C) auch für Höhenlagen bis ~1800 m geeignet. Essbar und sicher – aber Verwechslungsgefahr mit giftigen heimischen Heckenkirschen: nur gekaufte essbare Sorten verwenden. Braucht Befruchtersorte.','Tox Info Suisse (tox.ch) Lonicera-Differenzierung; Kamtschatka-Heckenkirsche Wikipedia / Baumschul-Fachliteratur (essbare var. kamtschatica)'),
('magnolia_soulangeana','Magnolia × soulangeana','Tulpen-Magnolie','Magnolia de Soulange','Magnolia di Soulange','Saucer magnolia','Magnolia de Soulange','zierbaum','4','6','3','5','langsam','15','breit-trichterförmig, oft mehrstämmig','laubabwerfend','flachwurzler','0.6',NULL,'mittel','sonnig bis halbschattig, windgeschützt','5','6.8','{humos,sandig-lehmig,durchlässig,frisch}','mittel bis hoch','5b-9a','-26',NULL,'900','{3,4,9,10}','2.0','1.5','t','1','f','3','2.5',NULL,'hoch','keine',NULL,'gering','t','f',NULL,'t','Schnitt vermeiden; falls nötig im Hochsommer (Juli/Aug) nach der Blüte, da spät blutend','Frühblüher – Blüten frostgefährdet, daher windgeschützten Spätfrost-armen Standort wählen. Fleischwurzler, empfindliche flache Wurzeln nicht stören. Mulchen, keinen Boden verdichten. Schnitt nur minimal.','{Magnolienschildlaus,"Frostschäden an Blüten","Sonnenbrand am Stamm (Weißanstrich jung)"}','In CH beliebter Vorgartenbaum im Mittelland; ungiftig, kinder-/haustiersicher. Flachwurzler – Abstand zu Wegen/Platten einhalten.','Baumschul-Fachliteratur, tox.ch (keine Listung); bestätigt tox=keine, safe=true'),
('malus_domestica','Malus domestica','Apfel (Kulturapfel)','Pommier','Melo','Apple','Manzano','obstbaum','3','6','2.5','5','mittel','8','rundlich bis breit ausladend, je nach Unterlage','laubabwerfend','herzwurzler','1.5',NULL,'gering','sonnig bis halbschattig','6','7.5','{lehmig,humos,tiefgruendig}','mittel','4-8','-30',NULL,'1000','{3,4,10,11}','2.0','1.5','t','1','t','2','2',NULL,'hoch','leicht','Samen (Kerne) enthalten cyanogene Glykoside (Amygdalin); Fruchtfleisch essbar','gering bis mittel (Rosaceae-Pollen, Apfelallergie bei Birkenpollen-Kreuzreaktion)','t','t','{"Malus domestica (andere Sorte)","Malus (Zierapfel)"}','f','Winter (Februar-März) und Sommerschnitt Juli/August','Spalier- oder Hochstamm; auf passende Unterlage achten (M9 schwachwuchsig, A2 stark). Regelmäßiger Erziehungs- und Auslichtungsschnitt. Pflanzpfahl bei schwachwüchsigen Unterlagen dauerhaft.','{Apfelwickler,Apfelschorf,Mehltau,Blutlaus,Feuerbrand}','Häufigster Obstbaum der Schweiz; Hochstamm-Apfelbäume sind kulturlandschaftsprägend und teils Direktzahlungs-förderfähig. Feuerbrand (Erwinia amylovora) meldepflichtig.','tox.ch / CliniTox UZH / Baumschul-Fachliteratur'),
('malus_evereste','Malus ''Evereste''','Zierapfel','Pommier d''ornement','Melo ornamentale','Crab apple','Manzano ornamental','zierbaum','4','6','3','5','mittel','12','kegelförmig bis breit-rund, dicht verzweigt','laubabwerfend','herzwurzler','1',NULL,'gering','sonnig bis licht halbschattig','5.5','7.5','{lehm,sandig-lehmig,humos,durchlässig}','mittel','4b-8a','-30',NULL,'1200','{3,4,10,11}','2.0','1.5','t','1','f','3','2',NULL,'hoch','leicht','Samen/Kerne (Amygdalin – cyanogen); Fruchtfleisch essbar/ungiftig','gering (insektenbestäubt)','f','f',NULL,'f','Winter (laubfrei, Nov–Feb) bzw. nach der Blüte für Formschnitt','Wertvoller Bienen-Pollenspender und guter Befruchter für Tafeläpfel. Zierfrüchte bleiben lang hängen, Vogelnahrung. Fruchtfleisch ungiftig, aber Kerne enthalten Amygdalin – größere Mengen zerkauter Kerne sind cyanogen.','{Apfelschorf,Mehltau,Feuerbrand,Blattläuse}','In CH sehr verbreiteter Hausbaum und Pollen-Befruchter für Obstwiesen. KORRIGIERT: child_pet_safe von true→false, da Kerne Amygdalin enthalten (konservativer Kinder-/Haustier-Schutz); Fruchtfleisch selbst ist harmlos.','tox.ch (Malus-Kerne Amygdalin), Baumschul-Fachliteratur; KORREKTUR child_pet_safe true→false (Kern-Toxizität, konservativ)'),
('mespilus_germanica','Mespilus germanica','Echte Mispel (Asperl)','Néflier commun','Nespolo comune','Medlar','Níspero europeo','obstbaum','3','6','3','5','langsam','6','breit ausladend, malerisch knorrig, oft überhängend','laubabwerfend','herzwurzler','1.2',NULL,'gering','sonnig bis halbschattig, warm geschützt','5.5','7.5','{lehm,humos,durchlässig,frisch,nährstoffreich}','mittel','5b-8','-25',NULL,'800','{3,4,10,11}','2.0','1.5','t','1','f','3','3',NULL,'hoch','keine','Früchte erst nach Frost/Teigreife (Lagerung) genießbar – roh hart und gerbstoffreich, aber nicht giftig. Kerne wie bei vielen Rosengewächsen nicht zerkauen (Blausäure-Spuren in Samen), Fruchtfleisch unbedenklich','gering','t','f',NULL,'t','Winter (Vegetationsruhe), wenig Schnitt nötig','Alte Obstart, malerischer Kleinbaum/Großstrauch mit großen weißen Blüten. Früchte (Mispeln/Asperln) erst nach Frost teigig weich essbar (Teigreife/Lagerung), traditionell für Mus/Gelee. Wärmeliebend, geschützter Standort. Veredelt meist auf Weißdorn/Quitte.','{"Feuerbrand (anfällig)",Birnengitterrost,Blattläuse}','Alte, selten gewordene Obstart für warme CH-Lagen bis ca. 800 m (Mittelland, Tessin). Erhaltenswert in Hausgärten und alten Obstgärten. Asperl als alemannischer Volksname.','tox.ch / Info Flora CH / ProSpecieRara / Baumschul-Fachliteratur'),
('morus_nigra','Morus nigra','Schwarze Maulbeere','Mûrier noir','Gelso nero','Black mulberry','Morera negra','obstbaum','6','12','6','10','langsam','10','breit rundlich, knorrig ausladend','laubabwerfend','herzwurzler','2',NULL,'hoch','sonnig, warm geschützt','6','7.5','{lehm,sandig-lehmig,nährstoffreich,durchlässig,warm}','mittel','6b-9','-20',NULL,'700','{4,5,10}','2.0','1.5','t','1','f','6','5',NULL,'forst','keine',NULL,'gering bis mittel (Pollen)','t','f',NULL,'t','Winter (Vegetationsruhe), Schnitt sparsam, blutet bei Frühjahrsschnitt','Wärmeliebend, braucht geschützten, sonnigen Standort. Reife Beeren stark färbend (Flecken auf Pflaster/Terrasse) → root_risk und Standort beachten, nicht über Sitzplatz/Belag pflanzen. Köstliche dunkle Beeren essbar. Langlebig, knorriger Charakterbaum. Frostempfindlicher als M. alba.','{Maulbeer-Schildlaus,"Spinnmilben (in Trockenheit)","selten Pilzkrankheiten"}','Wärmebedürftig – in der CH nur in milden, geschützten Lagen (Tessin, Genferseeregion, Wallis, warme Stadtlagen) bis ca. 700 m sinnvoll. Historisch mit Seidenraupenzucht im Tessin verbunden (dort eher M. alba).','tox.ch / Info Flora CH / Baumschul-Fachliteratur'),
('photinia_x_fraseri_red_robin','Photinia x fraseri ''Red Robin''','Glanzmispel (Rote Glanzmispel ''Red Robin'')','Photinia ''Red Robin''','Fotinia ''Red Robin''','Red-tip photinia ''Red Robin''','Fotinia ''Red Robin''','hecke','2','4','1','2.5','mittel','5','dicht aufrecht, rote Austriebe','immergruen','herzwurzler','0.7',NULL,'gering','Sonne bis Halbschatten','5.5','7.5','{lehmig,humos,durchlässig}','mittel','7a-9b','-15',NULL,'800','{4,5,9,10}','2.0','1.5','f','0','f','1','0.6','0.6','hoch','leicht','Samen/Kerne und welkende Blätter (geringe cyanogene Glykoside, Rosaceae-typisch)','gering','f','f',NULL,'t','nach Austrieb Mai-Juni (fördert rote Neutriebe)','Leicht giftig (Prunasin in Kernen/welken Blättern, wie viele Rosengewächse). Schnitt regt rote Austriebe an. Frostempfindlicher als andere Hecken — in CH-Höhenlagen geschützter Standort.','{"Feuerbrand (anzeigepflichtig!)","Echter Mehltau","Blattfleckenpilze (Entomosporium)"}','Feuerbrand-Wirtspflanze (Erwinia amylovora) — meldepflichtig in CH, Pflanzung in Obstbau-Schutzgebieten teils eingeschränkt. Frostschutz nötig über ~800m.','Baumschul-Fachliteratur, Agroscope Feuerbrand-Wirtsliste'),
('picea_abies','Picea abies','Gemeine Fichte (Rottanne)','Épicéa commun','Abete rosso','Norway spruce','Pícea común','nadelbaum','25','35','4','8','schnell','40','kegelförmig, schmal-pyramidal','immergruen','flachwurzler','1',NULL,'hoch','sonnig bis halbschattig','4','6.5','{lehmig,sandig-lehmig,frisch-feucht}','mittel bis hoch','3-7','-40',NULL,'2000','{3,4,9,10}','2.0','1.5','t','1','t','8','5',NULL,'forst','keine',NULL,'Pollen leicht allergen (Frühjahr), insgesamt gering','t','f',NULL,'t','selten nötig; ggf. Spätsommer (Aug)','Flachwurzler – windwurfgefährdet, nicht zu nah an Gebäude/Wege. Hauptbaum der CH-Forstwirtschaft, anfällig für Borkenkäfer bei Trockenstress.','{"Borkenkäfer (Buchdrucker)",Fichtengallenläuse,"Rote Spinne",Sirex-Holzwespe}','Wichtigster Waldbaum der Schweiz, bis ~2000 m ü. M. Gefährdet durch Trockenheit + Borkenkäfer im Mittelland; im Bergwald standortgerecht.','BAFU Waldbäume CH; tox.ch (ungiftig); Lauber/Wagner Flora Helvetica'),
('pinus_sylvestris','Pinus sylvestris','Waldföhre (Waldkiefer, Rotföhre)','Pin sylvestre','Pino silvestre','Scots pine','Pino silvestre','nadelbaum','20','30','4','8','mittel','40','jung kegelförmig, alt schirmförmig-malerisch','immergruen','pfahlwurzler','2.5',NULL,'gering','vollsonnig (Lichtbaumart)','4','7.5','{sandig,kiesig,trocken,mager,anspruchslos}','gering','3-7','-40',NULL,'2000','{3,4,9,10}','2.0','1.5','t','1','t','6','4',NULL,'forst','keine',NULL,'Pollen mäßig allergen (Mai), insgesamt gering','t','f',NULL,'t','selten nötig; Frühjahr','Pfahlwurzler – sehr sturmfest, geringes Gebäuderisiko, gedeiht auf armen Trockenstandorten. Vollsonne zwingend, verträgt keine Beschattung.','{Kiefernprozessionsspinner,Kieferntriebwickler,Diplodia-Triebsterben,Blasenrost}','Typisch für trockenwarme Föhrenwälder (Wallis, Churer Rheintal). Klimaresilient auf Trockenstandorten; im Wallis durch Mistel + Trockenheit lokal rückläufig.','BAFU Waldbäume CH; tox.ch (ungiftig); Flora Helvetica'),
('platanus_x_hispanica','Platanus x hispanica','Ahornblättrige Platane','Platane à feuilles d''érable','Platano comune','London plane','Plátano de sombra','hausbaum','20','35','15','25','schnell','40','breit, hoch gewölbt, ausladend','laubabwerfend','herzwurzler','2.5',NULL,'hoch','sonnig','5.5','8','{lehmig,sandig,durchlässig,stadtklimatolerant}','mittel','6a','-23',NULL,'800','{3,4,10,11}','2.0','1.5','t','2','f','10','8',NULL,'forst','keine',NULL,'Pollen mäßig bis stark (windbestäubt); Sternhaare der Früchte/junger Blätter wirken reizend auf Atemwege/Haut','t','f',NULL,'t','Winter (laublos); sehr schnittverträglich (Kandelaber-/Dachschnitt möglich)','Ungiftig. Hinweis: feine Sternhärchen der Früchte und austreibenden Blätter können Augen-/Atemwegsreizungen auslösen (mechanisch, nicht toxisch) — daher ''leicht'' im Input war eine Reizungs-, keine Giftigkeitsfrage; toxikologisch ungiftig. Sehr starker, flacher Wurzeldruck — kann Beläge/Fundamente schädigen, großzügigen Abstand halten. Extrem stadtklima- und schnittverträglich.','{"Massaria-Krankheit (Astbruchgefahr)",Platanen-Netzwanze,"Anthraknose (Apiognomonia)"}','In der Schweiz häufiger Allee-/Platzbaum in Städten (Stadtklimabaum). Wegen aggressivem Wurzeldruck und Endgröße großen Gebäudeabstand einhalten. Massaria-Monitoring bei Altbäumen (Verkehrssicherheit).','tox.ch (ungiftig; Reizung durch Sternhaare ist mechanisch), info flora CH, Stadtbaum-Literatur'),
('populus_nigra_italica','Populus nigra ''Italica''','Pyramidenpappel (Säulenpappel)','Peuplier d''Italie','Pioppo cipressino','Lombardy poplar','Chopo lombardo','hausbaum','20','30','3','6','schnell','15','säulenförmig, schmal aufrecht','laubabwerfend','flachwurzler','1.5',NULL,'hoch','sonnig','5.5','8','{"frisch bis feucht",lehmig,sandig,nährstoffreich}','hoch','4a','-37',NULL,'1000','{3,4,10,11}','2.0','1.5','t','2','f','12','8',NULL,'forst','keine',NULL,'Pollen mäßig; ''Italica'' ist männlicher Klon (keine Samenwolle), Pollen jedoch vorhanden','t','f',NULL,'f','Winter (laublos); schnittverträglich','Ungiftig. WARNUNG Wurzeln: aggressive, weit streichende Flachwurzeln auf Wassersuche — können Drainagen, Abwasserrohre, Fundamente und Beläge massiv schädigen. Mindestabstand 12 m zu Gebäuden/Leitungen. Schnellwüchsig aber kurzlebig und windbruchgefährdet (Äste). Nur für große, freie Flächen.','{"Pappelrost (Melampsora)",Pappelblattkäfer,"Bakterienkrebs (Xanthomonas)",Hallimasch}','Klassischer Klon der italienischen/Tessiner Alleen, bis ~1000 m. In der Schweiz wegen Wurzelschäden und Windbruch nur mit großem Abstand zu Infrastruktur pflanzen. Männlicher Klon — keine lästige Pappelwolle.','tox.ch (ungiftig), info flora CH, Baumschul-/Tiefbau-Literatur (Wurzelschäden)'),
('prunus_armeniaca','Prunus armeniaca','Aprikose (Marille)','Abricotier','Albicocco','Apricot','Albaricoquero','obstbaum','3','6','3','5','mittel','5','breit rundlich, ausladend','laubabwerfend','herzwurzler','1.8',NULL,'mittel','vollsonnig, warm und geschützt','6.5','8','{lehmig,kalkhaltig,durchlaessig,warm}','mittel','5-8','-24',NULL,'700','{3,4,10}','2.0','1.5','t','1','t','2.5','2.5',NULL,'hoch','leicht','Steinkerne enthalten besonders viel Amygdalin (hohe Blausäure-Freisetzung), zudem Rinde/Blätter; Fruchtfleisch essbar','gering bis mittel (Rosaceae-Pollen; Aprikosenallergie bei Birkenpollen-Kreuzreaktion)','f','f','{"Prunus armeniaca (andere Sorte)"}','t','nach der Ernte (Sommer) zur Gummifluss- und Monilia-Vermeidung; nie im Winter/Frost','Sehr früh blühend → spätfrostgefährdet, daher warme, geschützte Südlage (gerne Spalier an Hauswand). Aprikosenkerne haben hohen Cyanid-Gehalt — für Kinder/Haustiere gefährlich. Anfällig für Monilia und Apoplexie (Triebsterben).','{"Monilia (Spitzendürre)",Scharka-Virus,"Bakterienbrand (Pseudomonas)",Apoplexie}','Wallis (Valais) ist das CH-Aprikosen-Kerngebiet (Sorte Luizet). Spätfrostgefahr begrenzt Anbau in höheren/kälteren Lagen. Bittere Wildaprikosenkerne stark blausäurehaltig.','tox.ch / CliniTox UZH / ScienceDirect (Aprikosenkern-Cyanidtoxizität) / Baumschul-Fachliteratur'),
('prunus_avium','Prunus avium','Suesskirsche','Cerisier (merisier)','Ciliegio','Sweet cherry','Cerezo','obstbaum','8','18','5','10','schnell','10','hochgewölbt, ausladend, im Alter breit kegelförmig','laubabwerfend','herzwurzler','2',NULL,'mittel','sonnig','6','7.8','{lehmig,kalkhaltig,tiefgruendig,durchlaessig}','mittel','4-8','-30',NULL,'1200','{3,4,10,11}','2.0','1.5','t','1','t','5','4',NULL,'forst','leicht','Samen (Steinkerne), Rinde und frische/welkende Blätter enthalten cyanogene Glykoside (Prunasin, Amygdalin) → Blausäure; Fruchtfleisch essbar','gering bis mittel (Rosaceae-Pollen; Kirschallergie bei Birkenpollen-Kreuzreaktion)','f','t','{"Prunus avium (andere Sorte)","Prunus cerasus"}','f','direkt nach der Ernte (Juni-August) zur Vermeidung von Gummifluss; nie bei Frost','Starkwüchsiger Großbaum (Wildform = Vogelkirsche/Forstbaum). Welkendes Laub und Steinkerne für Weidetiere/Haustiere gefährlich. Empfindlich gegen Schnittwunden (Gummifluss, Monilia). Großzügigen Standabstand wählen.','{Kirschfruchtfliege,"Monilia (Spitzendürre)",Schrotschusskrankheit,Blattläuse}','Vogelkirsche ist heimischer Forst- und Landschaftsbaum (Mittelland-Hochstamm-Kirschkulturen z.B. Baselbiet/Fricktal). Als Wildbaum bis 25 m. Kerne und welkes Laub für Vieh giftig.','tox.ch / CliniTox UZH (vetpharm.uzh.ch) / Baumschul-Fachliteratur'),
('prunus_cerasifera_nigra','Prunus cerasifera ''Nigra''','Blutpflaume (Blut-Kirschpflaume)','Prunier-cerise pourpre ''Nigra''','Mirabolano rosso ''Nigra''','Purple-leaf cherry plum ''Nigra''','Ciruelo rojo ''Nigra''','zierbaum','5','7','3','5','mittel','12','rundlich bis breit-eiförmig','laubabwerfend','herzwurzler','1',NULL,'mittel','sonnig (Laubfärbung am besten in voller Sonne)','6','7.5','{lehm,sandig-lehmig,humos,durchlässig}','mittel','5a-8a','-28',NULL,'1000','{3,4,10,11}','2.0','1.5','t','1','f','3','2',NULL,'hoch','leicht','Blätter, Rinde, Kerne/Steine (cyanogene Glykoside, v.a. in welkem Laub)','gering (insektenbestäubt)','f','f',NULL,'t','nach der Blüte (Mai/Juni), bei trockenem Wetter; Prunus möglichst wenig schneiden','Früh- und auffällig rosa blühend, dunkelrotes Laub. Kleine essbare Pflaumen-Früchte (Fruchtfleisch ungiftig), aber Blätter/Kerne cyanogen. Welkes Laub besonders für Weidetiere/Pferde gefährlich. Schnitt sparsam wegen Gummifluss.','{Schrotschusskrankheit,Monilia,Blattläuse,Narren-/Taschenkrankheit}','In CH sehr häufiger Vorgarten-/Straßenbaum. cyanogene Glykoside in Blättern/Kernen – tox.ch listet Prunus als leicht giftig; welkes Laub nicht in Tierweiden. bestätigt tox=leicht, safe=false korrekt.','tox.ch (Prunus cyanogene Glykoside), ASPCA, Baumschul-Fachliteratur; bestätigt tox=leicht, safe=false'),
('prunus_cerasus','Prunus cerasus','Sauerkirsche (Weichsel)','Griottier (cerisier acide)','Amareno (ciliegio acido)','Sour cherry','Guindo','obstbaum','3','5','2.5','4','mittel','6','rundlich, kompakt, oft strauchartig mehrstämmig','laubabwerfend','flachwurzler','1.2',NULL,'gering','sonnig bis halbschattig','6','7.5','{lehmig,durchlaessig,kalktolerant}','mittel','4-8','-32',NULL,'1000','{3,4,10,11}','2.0','1.5','t','1','t','2.5','2',NULL,'hoch','leicht','Steinkerne, Rinde und Blätter mit cyanogenen Glykosiden; Fruchtfleisch essbar','gering bis mittel (Rosaceae-Pollen)','f','f',NULL,'t','nach der Ernte (Sommer); altes Fruchtholz regelmäßig auslichten','Meist selbstfruchtbar (z.B. Schattenmorelle), gute Wahl für Einzelbaum. Trägt am einjährigen Holz, daher konsequenter Verjüngungsschnitt. Kerne/Laub für Haustiere giftig.','{Monilia,Sprühfleckenkrankheit,Kirschfruchtfliege,Blattläuse}','Robuster und frosthärter als Süsskirsche, auch in höheren Lagen tragfähig. Schattenmorelle weit verbreitet in CH-Hausgärten.','tox.ch / CliniTox UZH / Baumschul-Fachliteratur'),
('prunus_domestica_subsp_domestica','Prunus domestica subsp. domestica','Zwetschge','Quetsche (prunier)','Susino (prugna)','Plum (European plum)','Ciruelo','obstbaum','4','6','3','5','mittel','6','rundlich bis breit eiförmig','laubabwerfend','herzwurzler','1.5',NULL,'mittel','sonnig','6','7.5','{lehmig,humos,naehrstoffreich}','mittel','4-8','-29',NULL,'1000','{3,4,10,11}','2.0','1.5','t','1','t','2.5','2.5',NULL,'hoch','leicht','Steinkerne, Rinde und Blätter enthalten cyanogene Glykoside; Fruchtfleisch essbar','gering (Rosaceae-Pollen)','f','f','{"Prunus domestica (andere Sorte)"}','t','nach der Ernte / Spätsommer (Gummifluss-Vermeidung); nie bei Frost','Viele Sorten (z.B. Hauszwetschge) selbstfruchtbar, Ertrag mit Pollenspender besser. Zur Scharka-Virose anfällig. Steinkerne/Laub für Haustiere giftig.','{"Scharka-Virus (Sharka)",Pflaumenwickler,Monilia,Pflaumensägewespe,Blattläuse}','Hauszwetschge traditioneller CH-Hochstammbaum (Most/Schnaps). Scharka-Virus regional verbreitet, befallene Bäume roden. Kerne/welkes Laub giftig für Vieh.','tox.ch / CliniTox UZH / Baumschul-Fachliteratur'),
('prunus_domestica_subsp_syriaca','Prunus domestica subsp. syriaca','Mirabelle','Mirabellier','Mirabella','Mirabelle plum','Ciruela mirabel','obstbaum','4','6','3','5','mittel','6','rundlich, dicht verzweigt','laubabwerfend','herzwurzler','1.5',NULL,'mittel','sonnig','6','7.5','{lehmig,humos,warm}','mittel','5-8','-26',NULL,'800','{3,4,10,11}','2.0','1.5','t','1','t','2.5','2.5',NULL,'hoch','leicht','Steinkerne, Rinde und Blätter mit cyanogenen Glykosiden; Fruchtfleisch essbar','gering (Rosaceae-Pollen)','f','f','{"Prunus domestica (andere Sorte)"}','t','nach der Ernte / Spätsommer; nie bei Frost','Meist selbstfruchtbar, reiche Erträge kleiner gelber Früchte. Wärmeliebend, geschützte Lage bevorzugen. Kerne/Laub für Haustiere giftig.','{Scharka-Virus,Pflaumenwickler,Monilia,Pflaumensägewespe}','In wärmeren CH-Lagen (Mittelland, Genferseeregion, Tessin) gut tragend. Selbstfruchtbar, ideal für Einzelbaum im Hausgarten.','tox.ch / CliniTox UZH / Baumschul-Fachliteratur'),
('prunus_laurocerasus','Prunus laurocerasus','Kirschlorbeer (Lorbeerkirsche)','Laurier-cerise','Lauroceraso','Cherry laurel','Laurel cerezo','hecke','2','5','1.5','4','schnell','5','dicht, breit ausladend, grossblättrig','immergruen','flachwurzler','0.8',NULL,'mittel','Halbschatten bis Schatten','5','7.5','{lehmig,humos,durchlässig,frisch}','mittel','6a-8b','-20',NULL,'900','{4,5,9,10}','2.0','1.5','f','0','f','1.5','1','0.6','hoch','stark','Blätter und Samen/Kerne (cyanogene Glykoside — Blausäure), Fruchtfleisch gering','gering','f','f',NULL,'t','April-Mai und August (Handschere statt Heckenschere — sonst braune Schnittränder)','Stark giftig: Blätter/Kerne setzen Blausäure frei (Prunasin/Amygdalin). Kerne der schwarzen Früchte gefährlich bei Kindern/Hunden. Schnittgut nicht häckseln/kompostieren in Tiernähe. In CH invasiv eingestuft — Verbreitung über Vögel.','{Schrotschusskrankheit,Dickmaulrüssler,"Echter Mehltau",Läuse}','Auf der Schwarzen Liste invasiver Neophyten (Info Flora); Verkauf/Neupflanzung seit 09/2024 in CH verboten. Stark giftig — tox.ch, Tox Info Suisse 145.','tox.ch (Kirschlorbeer-Beeren/Blausäure), Info Flora invasive Neophyten'),
('prunus_persica','Prunus persica','Pfirsich','Pêcher','Pesco','Peach','Melocotonero (duraznero)','obstbaum','3','5','2.5','4','schnell','4','breit rundlich, locker','laubabwerfend','flachwurzler','1',NULL,'gering','vollsonnig, warm und geschützt','6','7.5','{lehmig,sandig,durchlaessig,warm}','mittel bis hoch','5-8','-23',NULL,'600','{3,4,10}','2.0','1.5','t','1','t','2','2',NULL,'hoch','leicht','Steinkerne, Rinde und Blätter enthalten cyanogene Glykoside; Fruchtfleisch essbar','mittel (Rosaceae; Pfirsich-LTP-Allergie möglich)','f','f',NULL,'t','Frühjahr nach dem Austrieb bis kurz nach Blüte; trägt am vorjährigen Holz','Selbstfruchtbar, schnellwüchsig aber kurzlebig. Sehr anfällig für Kräuselkrankheit (Taphrina) — Standort mit Regenschutz/luftig wählen. Kurzlebig (oft nur 10-15 produktive Jahre). Kerne/Laub für Haustiere giftig.','{"Kräuselkrankheit (Taphrina deformans)",Monilia,Mehltau,Blattläuse}','Nur in wärmsten CH-Lagen (Tessin, Wallis, Genferseeregion, Stadtklima) zuverlässig. Kräuselkrankheit limitierender Faktor; Weinbergpfirsich (rotfleischig) traditionell verbreitet.','tox.ch / CliniTox UZH / Baumschul-Fachliteratur'),
('prunus_persica_var_nucipersica','Prunus persica var. nucipersica','Nektarine','Nectarine (brugnon)','Nettarina (pesca noce)','Nectarine','Nectarina','obstbaum','3','5','2.5','4','schnell','4','breit rundlich, locker','laubabwerfend','flachwurzler','1',NULL,'gering','vollsonnig, warm und geschützt','6','7.5','{lehmig,sandig,durchlaessig,warm}','mittel bis hoch','5-8','-23',NULL,'600','{3,4,10}','2.0','1.5','t','1','t','2','2',NULL,'hoch','leicht','Steinkerne, Rinde und Blätter enthalten cyanogene Glykoside; Fruchtfleisch essbar','mittel (Rosaceae; LTP-Allergie wie Pfirsich)','f','f',NULL,'t','Frühjahr nach dem Austrieb bis kurz nach Blüte; trägt am vorjährigen Holz','Glattschalige Mutation des Pfirsichs, selbstfruchtbar. Ebenso kräuselkrankheits-anfällig wie Pfirsich, etwas wärmebedürftiger. Kerne/Laub für Haustiere giftig.','{"Kräuselkrankheit (Taphrina deformans)",Monilia,Mehltau,Blattläuse}','Wie Pfirsich nur in wärmsten CH-Lagen (Tessin, Wallis) verlässlich. Wandspalier in geschützter Südlage empfohlen.','tox.ch / CliniTox UZH / Baumschul-Fachliteratur'),
('prunus_serrulata','Prunus serrulata','Japanische Zierkirsche (Nelkenkirsche)','Cerisier du Japon','Ciliegio giapponese da fiore','Japanese flowering cherry','Cerezo japonés de flor','zierbaum','5','8','3','6','mittel','15','trichterförmig bis breit ausladend, je nach Sorte schirmförmig','laubabwerfend','herzwurzler','1',NULL,'mittel','sonnig bis halbschattig','6','7.5','{lehm,sandig-lehmig,humos,durchlässig}','mittel','6a-8b','-23',NULL,'1000','{3,4,10,11}','2.0','1.5','t','1','f','3','2',NULL,'hoch','leicht','Blätter, Rinde, Samen/Kerne (cyanogene Glykoside)','gering (insektenbestäubt, wenig Pollenflug)','f','f',NULL,'t','direkt nach der Blüte (Mai/Juni); Prunus möglichst wenig schneiden wegen Gummifluss/Infektionsgefahr','Blütengehölz, keine essbaren Früchte. Empfindlich für Schrotschuss und Monilia. Schnitt nur bei trockenem Wetter, Wunden sauber halten. Veredelt – Wildtriebe unter der Veredlungsstelle entfernen.','{Schrotschusskrankheit,"Monilia (Spitzendürre)",Blattläuse,Blütenmonilia}','In CH als Allee- und Vorgartenbaum weit verbreitet; cyanogene Glykoside in Blättern/Kernen – tox.ch listet Prunus-Arten als leicht giftig. Kerne nicht von Kindern verschlucken lassen.','tox.ch (Prunus cyanogene Glykoside), Baumschul-Fachliteratur; korrigiert/bestätigt: tox=leicht, safe=false korrekt'),
('prunus_spinosa','Prunus spinosa','Schwarzdorn (Schlehe)','Prunellier','Prugnolo','Blackthorn (sloe)','Endrino','wildgehoelz','1.5','4','2','4','mittel','12','dicht, sparrig, stark dornig, Ausläufer bildend','laubabwerfend','flachwurzler','1',NULL,'mittel','sonnig','6','8','{lehmig,kalkhaltig,steinig,sandig}','gering bis mässig','4b','-34',NULL,'1600','{3,4,10,11}','2.0','1.5','f','0','t','2.5','1.5','0.8','mittel','leicht','Samen/Kerne und Blätter enthalten cyanogene Glykoside (Amygdalin); Fruchtfleisch der reifen Schlehe essbar','gering','t','f',NULL,'t','nach der Blüte oder im Spätwinter; Wurzelausläufer regelmässig entfernen','Bildet starke Wurzelausläufer - kann sich invasiv ausbreiten, Rhizomsperre bei kleinen Gärten erwägen. Frühe Bienenweide, Raupenfutterpflanze. Reife Schlehen erst nach Frost geniessbar.','{Schlehenwickler,Pflaumenrost,Schrotschusskrankheit}','Heimisch, ökologisch wertvoll (Schmetterlingsfutterpflanze). Achtung Ausläuferbildung - nicht direkt an Grundstücksgrenzen ohne Sperre.','tox.ch, InfoFlora, BAFU Wildgehölze, Baumschul-Fachliteratur'),
('pseudotsuga_menziesii','Pseudotsuga menziesii','Douglasie (Gewöhnliche Douglasie)','Douglas vert (Sapin de Douglas)','Abete di Douglas','Douglas fir','Abeto de Douglas','nadelbaum','30','45','6','10','schnell','40','kegelförmig, regelmäßig, dicht','immergruen','herzwurzler','1.8',NULL,'mittel','sonnig bis halbschattig','4.5','7','{lehmig,sandig-lehmig,tiefgründig,durchlässig}','mittel','4-7','-30',NULL,'1200','{3,4,9,10}','2.0','1.5','t','1','t','8','5',NULL,'forst','keine',NULL,'gering','t','f',NULL,'t','selten nötig; Spätsommer','Nordamerikanische Gastbaumart, raschwüchsig und sturmstabiler als Fichte (Herzwurzler). Frischer Trieb mit zitronigem Duft. Frostempfindlich im Austrieb (Spätfrostlagen meiden).','{"Douglasienwolllaus (Gilletteella)","Rußige Douglasienschütte (Nadelpilz)","Borkenkäfer (selten)"}','Wichtige eingeführte Forstart, gilt als klimaresiliente Fichten-Alternative im Mittelland. Wird wegen Invasivitätsdiskussion standörtlich kontrolliert eingesetzt.','BAFU/WSL Douglasie CH; tox.ch (ungiftig)'),
('pyrus_communis','Pyrus communis','Birne (Kulturbirne)','Poirier','Pero','Pear','Peral','obstbaum','4','8','3','5','mittel','8','aufrecht pyramidal bis hochgewölbt','laubabwerfend','tiefwurzler','2.5',NULL,'mittel','sonnig','6','7.5','{lehmig,tiefgruendig,naehrstoffreich}','mittel','4-8','-28',NULL,'900','{3,4,10,11}','2.0','1.5','t','1','t','2.5','2.5',NULL,'hoch','leicht','Samen (Kerne) enthalten cyanogene Glykoside; Fruchtfleisch essbar','gering (Rosaceae-Pollen)','t','t','{"Pyrus communis (andere Sorte)"}','f','Winter (Februar-März); Birne verträgt weniger starken Schnitt als Apfel','Tiefwurzler mit Pfahlwurzel-Tendenz, daher etwas größerer Gebäudeabstand. Auf Quitten-Unterlage schwachwüchsiger. Feuerbrand-anfällig.','{Birnengitterrost,Birnenpockenmilbe,Feuerbrand,Birnblattsauger}','Mostbirnen (z.B. Wässerwasser) traditionell in CH-Hochstammkulturen. Birnengitterrost durch Wacholder-Nachbarschaft (Wirtswechsel) verstärkt. Feuerbrand meldepflichtig.','tox.ch / CliniTox UZH / Baumschul-Fachliteratur'),
('quercus_robur','Quercus robur','Stieleiche','Chêne pédonculé','Farnia','English oak','Roble común','hausbaum','25','40','15','25','langsam','60','breit ausladend, unregelmäßig','laubabwerfend','pfahlwurzler','4',NULL,'mittel','sonnig (Lichtbaumart)','4.5','7.5','{lehmig,tiefgründig,"frisch bis feucht",nährstoffreich}','mittel','5a','-30',NULL,'1000','{3,4,10,11}','2.0','1.5','t','2','t','8','6',NULL,'forst','leicht','Eicheln, junge Blätter und Knospen (Gerbstoffe/Tannine); roh in Menge giftig','Pollen stark (windbestäubt, Frühjahrs-Allergen)','f','f',NULL,'t','Sommer (Juli/August) im belaubten Zustand; Totholz ganzjährig','Eicheln und junge Blätter enthalten Gerbstoffe (Tannine) — roh und in größerer Menge schädlich für Mensch, Hunde und besonders Weidetiere (Rinder/Pferde: Eichelvergiftung). Kindersicherheit: rohe Eicheln nicht verzehren. Tiefe Pfahlwurzel — fundamentschonend, aber sehr langlebig und groß, nur für große Grundstücke.','{"Eichenprozessionsspinner (Brennhaare-Gefahr!)",Eichenmehltau,Eichenwickler,Gallwespen}','Heimische Eiche der Schweiz bis ~1000 m, v.a. Tieflagen/Auen. Achtung Eichenprozessionsspinner (Gesundheitsgefahr durch Brennhaare). Eicheln für Weidetiere und Hunde giftig.','tox.ch / CliniTox (Quercus, Gerbstoffe), info flora CH'),
('ribes_nigrum','Ribes nigrum','Schwarze Johannisbeere (Cassis)','Cassissier','Ribes nero','Blackcurrant','Grosellero negro','beerenstrauch','1.2','1.8','1','1.5','mittel','3','buschig aufrecht, mehrtriebig','laubabwerfend','flachwurzler','0.5',NULL,'gering','sonnig bis halbschattig','6','7','{lehmig,humos,nährstoffreich}','mittel bis hoch','3-7','-30',NULL,'1400','{3,4,10,11}','2.0','1.5','f','0','f','1','0.5','1.2','niedrig','keine',NULL,'gering','t','f',NULL,'t','nach der Ernte (trägt am einjährigen Holz)','Trägt überwiegend am einjährigen Holz – jährlich altes Holz entfernen, junge Triebe fördern. Höherer Nährstoff- und Wasserbedarf als Rote Johannisbeere. Aromatische, vitamin-C-reiche Beeren.','{"Johannisbeergallmilbe (Brennessel-Symptom)",Blattläuse,Säulenrost,Mehltau}','In CH als Cassis verbreitet, kinder- und haustiersicher. Gallmilbe ist Hauptproblem – resistente Sorten wählen. Bis ~1400 m.','Tox Info Suisse (tox.ch) – nicht giftig gelistet; Baumschul-Fachliteratur'),
('ribes_rubrum','Ribes rubrum','Rote Johannisbeere','Groseillier rouge','Ribes rosso','Red currant','Grosellero rojo','beerenstrauch','1','1.5','1','1.5','mittel','3','buschig aufrecht, mehrtriebig','laubabwerfend','flachwurzler','0.5',NULL,'gering','sonnig bis halbschattig','6','7','{lehmig,humos,durchlässig}','mittel','3-7','-30',NULL,'1400','{3,4,10,11}','2.0','1.5','f','0','f','1','0.5','1','niedrig','keine',NULL,'gering','t','f',NULL,'t','nach der Ernte / Winter (Altholz auslichten)','Beliebter, anspruchsloser Beerenstrauch. Regelmäßiger Auslichtungsschnitt fördert Ertrag, da am 2-3-jährigen Holz tragend. Mulchen hält Flachwurzler feucht.','{Blattläuse,Johannisbeer-Blasenlaus,Stachelbeermehltau,Blattfallkrankheit}','In CH weit verbreiteter Hausgarten-Beerenstrauch, kinderfreundlich. Bis ~1400 m ü. M. problemlos. Kein Wurzelrisiko, nah an Gebäuden pflanzbar.','Tox Info Suisse (tox.ch) – nicht giftig gelistet; Baumschul-Fachliteratur'),
('ribes_uva_crispa','Ribes uva-crispa','Stachelbeere','Groseillier à maquereau','Uva spina','Gooseberry','Grosellero espinoso','beerenstrauch','0.9','1.3','1','1.3','mittel','3','buschig, bedornt, mehrtriebig','laubabwerfend','flachwurzler','0.5',NULL,'gering','sonnig bis halbschattig','6','7','{lehmig,humos,durchlässig}','mittel','3-7','-28',NULL,'1400','{3,4,10,11}','2.0','1.5','f','0','f','1','0.5','1','niedrig','keine',NULL,'gering','t','f',NULL,'t','Winter / nach der Ernte (auslichten für Luftzirkulation)','Bedornt – beim Schnitt Handschuhe. Mehltau-anfällig: luftigen Standort und Auslichtungsschnitt sicherstellen, mehltauresistente Sorten bevorzugen. Beeren essbar (grün bis rot/gelb).','{"Amerikanischer Stachelbeermehltau","Stachelbeerblattwespe (Kahlfraß)",Blattläuse}','Klassischer CH-Hausgarten-Strauch, essbar und sicher. Dornen kein Giftrisiko, aber Verletzungsgefahr für Kleinkinder beachten. Bis ~1400 m.','Tox Info Suisse (tox.ch) – nicht giftig gelistet; Baumschul-Fachliteratur'),
('ribes_x_nidigrolaria','Ribes x nidigrolaria','Jostabeere','Josta (caseille)','Josta','Jostaberry','Jostaberry','beerenstrauch','1.5','2','1.5','2','schnell','3','kräftig buschig, dornenlos, mehrtriebig','laubabwerfend','flachwurzler','0.6',NULL,'gering','sonnig bis halbschattig','6','7','{lehmig,humos,nährstoffreich}','mittel bis hoch','3-7','-30',NULL,'1400','{3,4,10,11}','2.0','1.5','f','0','f','1','1','1.5','niedrig','keine',NULL,'gering','t','f',NULL,'t','nach der Ernte / Winter (altes Holz auslichten)','Kreuzung Schwarze Johannisbeere × Stachelbeere – dornenlos, wüchsig und robust gegen Mehltau und Gallmilbe. Braucht mehr Platz. Beeren essbar, zwischen Johannis- und Stachelbeere im Geschmack.','{"Blattläuse (selten)","gelegentlich Blattfallkrankheit"}','In CH zunehmend beliebt wegen Krankheitsresistenz und Dornenlosigkeit – kinderfreundlich. Platzbedarf beachten. Bis ~1400 m.','Tox Info Suisse (tox.ch) – nicht giftig gelistet; Baumschul-Fachliteratur'),
('rosa_canina','Rosa canina','Hundsrose (Heckenrose)','Églantier (rosier des chiens)','Rosa canina (rosa selvatica)','Dog rose','Rosal silvestre (escaramujo)','wildgehoelz','1.5','3.5','1.5','3','schnell','8','überhängend, bogig, stark bestachelt','laubabwerfend','tiefwurzler','2',NULL,'gering','sonnig','5.5','7.5','{lehmig,sandig,kalkhaltig,humos}','gering bis mässig','4a','-37',NULL,'1800','{3,4,10,11}','2.0','1.5','f','0','t','1.5','1','0.8','mittel','keine',NULL,'gering (Samenhaare/Juckpulver im Hagebutten-Inneren mechanisch reizend, nicht giftig)','t','f',NULL,'t','Spätwinter oder nach der Blüte; verträgt Rückschnitt gut','Hagebutten sehr vitaminreich (Vitamin C), essbar - traditionell für Tee/Konfitüre. Bienenweide (Pollen). Stacheln bieten Vogelschutz. Robuste Wildrose, kaum krankheitsanfällig. Achtung: Samenhärchen in der Hagebutte sind das klassische ''Juckpulver'' (mechanisch, ungiftig).','{Rosenrost,Blattläuse,"Sternrusstau (selten an Wildrose)"}','Heimisch, eine der häufigsten Wildrosen der Schweiz. Hagebutten essbar, ökologisch wertvoll für Vögel und Insekten.','tox.ch, InfoFlora, BAFU Wildgehölze, Baumschul-Fachliteratur'),
('rubus_fruticosus_agg','Rubus fruticosus agg.','Brombeere (Kultursorte, dornenlos)','Mûrier (ronce) sans épines','Mora (rovo) senza spine','Thornless blackberry','Zarzamora sin espinas','beerenstrauch','2','3','1.5','3','schnell','2','rankend/kletternd, rutenartig, dornenlos (Kultursorte)','laubabwerfend','flachwurzler','0.6',NULL,'gering','sonnig bis halbschattig','5.5','7','{humos,lehmig,durchlässig}','mittel','5-8','-20',NULL,'1200','{4,5,9,10}','2.0','1.5','t','1','f','0.5','1','2','mittel','keine',NULL,'gering','t','f',NULL,'t','nach Ernte abgetragene Ruten entfernen; Jungruten anbinden','Dornenlose Kultursorten (z. B. ''Navaho'',''Thornless Evergreen'') sind handfreundlich. Kräftiges Spalier nötig, da lange Ruten. Trägt am zweijährigen Holz. Etwas frostempfindlicher als Himbeere – geschützter Standort, ggf. Winterschutz der Ruten.','{"Brombeermilbe (Roterscheinen der Früchte)",Blattläuse,Rost,"Graufäule (Botrytis)"}','In CH gut bis ~1200 m; in Höhenlagen frostgeschützter Standort wählen. Essbar und sicher. Dornenlose Sorten für Familiengärten ideal. Ruten brauchen Rankgerüst.','Tox Info Suisse (tox.ch) – nicht giftig gelistet; Baumschul-Fachliteratur'),
('rubus_idaeus','Rubus idaeus','Himbeere','Framboisier','Lampone','Raspberry','Frambueso','beerenstrauch','1.5','2','0.5','1.5','schnell','2','rutenartig aufrecht, Ausläufer bildend','laubabwerfend','flachwurzler','0.4',NULL,'gering','sonnig bis halbschattig','5.5','6.5','{humos,durchlässig,sandig-lehmig}','mittel bis hoch','3-8','-28',NULL,'1600','{3,4,10,11}','2.0','1.5','t','1','f','0.5','0.5','0.5','niedrig','keine',NULL,'gering','t','f',NULL,'t','Sommerhimbeere: nach Ernte abgetragene Ruten raus; Herbsthimbeere: Winter bodennah abschneiden','Ruten brauchen Spalier/Drahtgerüst. Bildet stark Ausläufer – Wurzelsperre oder Rhizombegrenzung empfohlen. Sauren, humosen Boden bevorzugen. Sommer- vs. Herbstsorten unterschiedlich schneiden.','{"Himbeerkäfer (Madenbefall)",Rutenkrankheit,"Wurzelfäule (Phytophthora bei Staunässe)",Spinnmilben}','In CH bis in mittlere Höhenlagen (~1600 m) sehr beliebt. Essbar und sicher; Ausläufer-Drang im Hausgarten eindämmen. Spalier nötig.','Tox Info Suisse (tox.ch) – nicht giftig gelistet; Baumschul-Fachliteratur'),
('salix_alba','Salix alba','Silberweide','Saule blanc','Salice bianco','White willow','Sauce blanco','hausbaum','15','25','10','18','schnell','20','breit, locker überhängend','laubabwerfend','flachwurzler','1.5',NULL,'hoch','sonnig','5.5','8','{"feucht bis nass",lehmig,auenboden,nährstoffreich}','hoch','3','-40',NULL,'1500','{3,4,10,11}','2.0','1.5','t','2','f','12','8',NULL,'forst','keine',NULL,'Pollen gering bis mäßig (insektenbestäubt); wichtige frühe Bienen-/Insektenweide (Kätzchen)','t','f',NULL,'f','Winter bis zeitiges Frühjahr; sehr schnittverträglich (Kopfweiden-Schnitt)','Ungiftig (Rinde enthält Salicin — pharmakologische Aspirin-Vorstufe, in Gartenmengen unbedenklich; nicht gezielt verzehren). WARNUNG Wurzeln: starke, wasserziehende Flachwurzeln — Drainagen, Rohre und Fundamente gefährdet, Mindestabstand 12 m. Liebt feuchte/nasse Standorte und Gewässerränder. Brüchige Äste — Windbruchgefahr. Schnellwüchsig, kurzlebig.','{"Weidenrost (Melampsora)",Weidenblattkäfer,"Bakterienbrand (Watermark disease)",Marssonina}','Heimischer Auen- und Uferbaum der Schweiz bis ~1500 m, wertvoll für Renaturierung und als frühe Bienenweide. Wegen Wurzeldruck und brüchigem Holz nicht nahe Gebäuden/Wegen. Ideal an Gewässern, nicht im Kleingarten.','tox.ch (ungiftig; Salicin pharmakologisch, nicht relevant giftig), info flora CH'),
('salix_caprea','Salix caprea','Salweide','Saule marsault','Salicone','Goat willow (pussy willow)','Sauce cabruno','wildgehoelz','4','10','3','6','schnell','15','rundlich bis breit, locker, mehrstämmig möglich','laubabwerfend','herzwurzler','2',NULL,'mittel','sonnig','5','7.5','{feucht,lehmig,sandig,humos}','hoch','4a','-37',NULL,'2000','{3,4,10,11}','2.0','1.5','t','1','t','4','2.5',NULL,'hoch','keine',NULL,'mittel (Weidenpollen können Allergiker reizen; Salweide ist insektenbestäubt, daher geringer Pollenflug als windbestäubte Arten)','t','t','{"zweihäusig - männliche und weibliche Pflanzen nötig für Samen; für Blüten-/Insektenwert genügt ein Exemplar"}','f','nach der Blüte (März/April) oder im Winter; sehr schnittverträglich, Kopfweidenschnitt möglich','Eine der WICHTIGSTEN frühen Bienenweiden (gelbe Kätzchen, Pollen+Nektar im März, zweihäusig - Männchen für Pollen wertvoller). Wurzeln wassersuchend - Abstand zu Drainagen/Leitungen halten (root_risk mittel). Schnellwüchsig.','{Weidenblattkäfer,Weidenbohrer,Rost}','Heimisch, ökologisch eine der wertvollsten Frühblüher-Insektennährpflanzen der Schweiz. Zweihäusig. Feuchteliebend - nicht für Trockenstandorte.','tox.ch, InfoFlora, BAFU Wildgehölze, Baumschul-Fachliteratur'),
('sambucus_nigra','Sambucus nigra','Schwarzer Holunder (Holler, Fliederbeere)','Sureau noir','Sambuco nero','Black elder (elderberry)','Saúco negro','wildgehoelz','3','7','2.5','5','schnell','4','breit ausladend, mehrstämmig, überhängend','laubabwerfend','flachwurzler','0.8',NULL,'gering','sonnig bis halbschattig','5.5','7.5','{nährstoffreich,stickstoffreich,frisch,humos,lehm}','mittel bis hoch','4-8','-30',NULL,'1500','{3,4,10,11}','2.0','1.5','f','0','f','2.5','2','2','hoch','leicht','Blätter, Rinde, unreife Beeren und die Samen reifer Beeren enthalten das cyanogene Glykosid Sambunigrin – roh genossen Übelkeit, Erbrechen, Durchfall (v.a. bei Kindern und unreifen/rohen Beeren). Durch Erhitzen über ca. 76 °C zerstört → gekocht unbedenklich','gering bis mittel (Pollen, Blütenduft)','f','f',NULL,'t','Winter (Februar) bis zeitiges Frühjahr; verträgt starken Rückschnitt','Sehr wüchsig und anspruchslos, liebt stickstoffreiche, frische Böden (Nährstoffzeiger). Beeren NUR gekocht/erhitzt verwenden (Saft, Gelee, Sirup) – roh leicht giftig durch Sambunigrin. Blüten essbar (Holunderküchle/Sirup). Kindersicherheit: roh giftige Beeren → child_pet_safe=false.','{"Schwarze Holunderblattlaus",Holunder-Spinnmilbe,"Echter Mehltau"}','Heimisches Wildgehölz in der ganzen CH bis 1500 m, häufig an Wegrändern, Hofnähe und in Hecken (Stickstoffzeiger). Wichtiges Vogelnährgehölz und Bienenweide. Traditionell Holunderblütensirup und gekochter Holundersaft.','tox.ch / phytotherapie-seminare.ch / ebi-pharm.ch / Info Flora CH'),
('sorbus_aucuparia','Sorbus aucuparia','Vogelbeere (Eberesche)','Sorbier des oiseleurs','Sorbo degli uccellatori','Rowan (mountain ash)','Serbal de cazadores','wildgehoelz','6','12','4','6','mittel','20','locker, rundlich bis eiförmig, aufrecht','laubabwerfend','herzwurzler','1.5',NULL,'gering','sonnig bis halbschattig','4.5','7.5','{sandig,lehmig,humos,sauer}','mässig','3b','-40',NULL,'2400','{3,4,10,11}','2.0','1.5','t','1','t','3','2',NULL,'hoch','leicht','rohe Beeren enthalten Parasorbinsäure (Magen-Darm-Reizung roh); durch Kochen/Frost abgebaut, dann verarbeitbar; Kerne enthalten cyanogene Glykoside','gering','t','f',NULL,'t','im Winter (laublos) bei Bedarf, Sorbus verträgt Schnitt schlecht - sparsam','Pioniergehölz, extrem frosthart bis hohe Lagen. Sehr wertvoll als Vogelnährgehölz (Beeren). Roh sind Beeren nur leicht reizend - keine ernste Gefahr, aber nicht roh verzehren.','{Feuerbrand,Birnengitterrost,Vogelbeer-Blattlaus}','Heimisch, klassischer Gebirgsbaum bis 2400m. Eine der wichtigsten Vogelnährpflanzen der Schweiz. Feuerbrand-Wirt.','tox.ch, InfoFlora, BAFU Wildgehölze, Baumschul-Fachliteratur'),
('sorbus_domestica','Sorbus domestica','Speierling','Cormier (sorbier domestique)','Sorbo domestico','Service tree','Serbal común','obstbaum','12','20','6','10','langsam','15','rundlich bis breit eiförmig','laubabwerfend','tiefwurzler','2.5',NULL,'gering','sonnig, warm','6','8','{lehm,kalkhaltig,tiefgründig,trocken-warm,durchlässig}','gering bis mittel','5b-8','-27',NULL,'900','{3,4,10,11}','2.0','1.5','t','2','t','6','5',NULL,'forst','keine','Früchte erst teigig-überreif genießbar (roh hart und sehr gerbstoffreich/adstringierend, aber nicht giftig)','gering','t','f',NULL,'t','Winter (Vegetationsruhe), sehr wenig Schnitt nötig','Wärmeliebender, langsam wachsender, sehr langlebiger Charakterbaum. Trockenheits- und kalktolerant. Früchte (Speierlinge) erst teigig-überreif essbar, traditionell für Most/Schnaps. Selten geworden, ökologisch und genetisch wertvoll.','{"Feuerbrand (anfällig)",Birnengitterrost,"Spinnmilben (Trockenstress)"}','In der CH selten und schützenswert, wärmeliebend – warme, kalkreiche Lagen im Mittelland/Jura bis ca. 900 m. Förderungswürdige seltene heimische Baumart (forstlich/ökologisch wertvoll).','tox.ch / BAFU / Info Flora CH / WSL seltene Baumarten'),
('sorbus_torminalis','Sorbus torminalis','Elsbeere (Schweizer Birnbaum)','Alisier torminal','Ciavardello','Wild service tree','Mostajo (serbal silvestre)','wildgehoelz','15','25','8','12','langsam','15','rundlich bis breit, locker','laubabwerfend','tiefwurzler','2.5',NULL,'gering','sonnig bis halbschattig, warm','6','8','{kalkhaltig,lehm,tiefgründig,trocken-warm,durchlässig}','gering bis mittel','5b-8','-27',NULL,'1000','{3,4,10,11}','2.0','1.5','t','2','t','6','5',NULL,'forst','keine','Früchte erst überreif/teigig genießbar (roh sehr gerbstoffreich/adstringierend, nicht giftig)','gering','t','f',NULL,'t','Winter (Vegetationsruhe), wenig Schnitt','Wärmeliebende, langsam wachsende, langlebige Edellaubbaumart mit sehr wertvollem Holz. Trockenheits- und kalktolerant. Lichtbedürftig im Bestand. Früchte (Elsbeeren) überreif essbar, traditionell für Schnaps. Schöne Herbstfärbung.','{"Feuerbrand (gelegentlich)",Birnengitterrost,Mehltau}','Heimische, seltene Edellaubbaumart der warmen, kalkreichen Lagen im Mittelland/Jura bis ca. 1000 m. Förderungswürdig, ökologisch wertvoll. ''Schweizer Birnbaum'' als Volksname; geschätztes Möbelholz.','tox.ch / BAFU / Info Flora CH / WSL seltene Baumarten'),
('taxus_baccata','Taxus baccata','Eibe (Gemeine Eibe)','If commun','Tasso comune','European yew','Tejo común','hecke','2','4','1','3','langsam','12','dicht, als Hecke sehr formstabil; als Baum breit','immergruen','herzwurzler','1',NULL,'gering','Sonne bis tiefer Schatten','5','8','{lehmig,humos,durchlässig,kalkhaltig}','mittel','6a-7b','-25',NULL,'1400','{4,5,9,10}','2.0','1.5','f','0','f','1','0.6','0.4','hoch','toedlich','alle Teile ausser rotem Samenmantel; Nadeln, Samen, Rinde, Holz (Taxin-Alkaloide)','gering','f','f',NULL,'f','April-September (jederzeit, verträgt Rückschnitt ins alte Holz)','TÖDLICH GIFTIG: Taxin-Alkaloide in Nadeln und Samen — wenige Nadeln/Samen können Herzstillstand auslösen, kein Gegengift. Höchste Giftstufe (+++). Schnittgut nie für Tiere zugänglich. Roter Samenmantel selbst ungiftig, aber Kern darin tödlich.','{Dickmaulrüssler,Eibengallmücke,"Wurzelfäule bei Staunässe"}','Einheimisch, geschützt. Häufigste tödliche Heckengiftpflanze — kritisch bei Kindern, Pferden, Rindern. Bei Verdacht sofort Tox Info Suisse 145.','tox.ch (höchste Stufe +++), vetpharm.uzh.ch, BAFU'),
('thuja_occidentalis','Thuja occidentalis','Abendländischer Lebensbaum (Thuja)','Thuya occidental','Tuia occidentale','Northern white cedar','Tuya occidental','hecke','2','5','0.8','2','mittel','8','dicht kegelförmig, als Hecke säulenartig','immergruen','flachwurzler','0.6',NULL,'mittel','Sonne bis Halbschatten','5','8','{lehmig,humos,frisch,kalkhaltig}','hoch','3a-7b','-34',NULL,'1300','{4,5,9,10}','2.0','1.5','f','0','f','1','0.6','0.5','hoch','stark','alle Teile, v.a. Triebspitzen und Zapfen (Thujon, ätherische Öle)','mittel (Kontaktdermatitis, Pollen)','f','f',NULL,'f','April-August (nicht ins alte Holz — treibt nicht nach)','Stark giftig: Thujon — Erbrechen, Krämpfe, in schweren Fällen Koma, Leber-/Nierenschäden (tox.ch). Hautreizend bei Schnitt (Handschuhe). Flachwurzler, Staunässe meiden, hoher Wasserbedarf. Braun bei Trockenheit.','{Thuja-Miniermotte,Borkenkäfer,"Wurzelfäule (Phytophthora)",Pestalotia-Triebsterben}','Sehr häufige Sichtschutzhecke, ökologisch arm (keine Nahrung für Insekten/Vögel). Kontakt mit Schnittgut für Kinder/Tiere meiden. Tox Info Suisse 145.','tox.ch (stark, Thujon — Koma/Krämpfe in schweren Fällen), Baumschul-Fachliteratur'),
('tilia_cordata','Tilia cordata','Winterlinde','Tilleul à petites feuilles','Tiglio selvatico','Small-leaved lime','Tilo de hoja pequeña','hausbaum','18','30','10','18','mittel','40','dicht, eiförmig bis rundlich','laubabwerfend','herzwurzler','2.5',NULL,'mittel','sonnig bis halbschattig','5.5','7.5','{lehmig,frisch,nährstoffreich}','mittel','4b','-34',NULL,'1200','{3,4,10,11}','2.0','1.5','t','2','f','7','5',NULL,'forst','keine',NULL,'Pollen mäßig; Blüten als Lindenblütentee genutzt (ungiftig)','t','f',NULL,'t','Spätwinter (Februar) oder nach der Blüte; schnittverträglich','Härter und etwas kleiner als Sommerlinde, blüht 2-3 Wochen später. Sehr wertvolle späte Bienenweide. Stadtklimatolerant. Langlebig.','{"Blattläuse (Honigtau)",Lindenspinnmilbe,Lindengallmücke}','Klimaresilientere Linden-Art für die Schweiz, bis ~1200 m. Häufig als Allee- und Parkbaum. Honigtau verklebt Beläge unter der Krone.','tox.ch (ungiftig), info flora CH, Baumschul-Fachliteratur'),
('tilia_platyphyllos','Tilia platyphyllos','Sommerlinde','Tilleul à grandes feuilles','Tiglio nostrano','Large-leaved lime','Tilo de hoja grande','hausbaum','20','35','12','20','mittel','40','breit gewölbt, rundlich','laubabwerfend','herzwurzler','2.5',NULL,'mittel','sonnig bis halbschattig','6','7.5','{lehmig,frisch,nährstoffreich,tiefgründig}','mittel','5a','-30',NULL,'1000','{3,4,10,11}','2.0','1.5','t','2','f','8','6',NULL,'forst','keine',NULL,'Pollen mäßig, Blüten stark duftend (Bienenweide)','t','f',NULL,'t','Spätwinter (Februar) oder nach der Blüte; verträgt starken Rückschnitt','Klassischer Allee- und Hofbaum, sehr langlebig (200+ Jahre). Blüht früher als Winterlinde. Wertvolle Bienenweide. Großer Platzbedarf, nicht für Kleingärten.','{Lindenspinnmilbe,"Blattläuse (Honigtau)",Lindengallmilbe}','In der Schweiz traditioneller Dorflinde-Baum, bis ~1000 m verbreitet. Wegen Größe Mindestabstand zu Gebäuden einhalten.','tox.ch (ungiftig), Baumschul-Fachliteratur, info flora CH'),
('tsuga_heterophylla','Tsuga heterophylla','Westamerikanische Hemlocktanne (Hemlock)','Pruche de l''Ouest','Tsuga occidentale','Western hemlock','Tsuga occidental','nadelbaum','20','30','5','9','mittel','40','kegelförmig mit charakteristisch überhängender Spitze','immergruen','flachwurzler','1',NULL,'mittel','schattig bis halbschattig (sehr schattenertragend)','4','6.5','{humos,frisch-feucht,sauer,durchlässig}','hoch','5-7','-28',NULL,'1200','{3,4,9,10}','2.0','1.5','t','1','t','6','4',NULL,'forst','keine',NULL,'gering','t','f',NULL,'t','Spätsommer; gut schnittverträglich','Nicht zu verwechseln mit dem giftigen Schierling (Conium/''poison hemlock'') – die Hemlocktanne ist ungiftig. Sehr schattentolerant, braucht gleichmäßige Feuchtigkeit, leidet bei Trockenheit/Hitze. Flachwurzler.','{"Hemlock-Wolllaus (Adelges tsugae)",Nadelpilze,Trockenstress-Schäden}','Selten gepflanzte Gastbaumart in Parks/Versuchsflächen, bevorzugt luftfeuchte, kühle Lagen. Wegen Trockenheitsempfindlichkeit im CH-Mittelland nur eingeschränkt klimatauglich.','WSL Gastbaumarten; tox.ch (ungiftig); Krüssmann Nadelgehölze'),
('vaccinium_corymbosum','Vaccinium corymbosum','Heidelbeere (Kulturheidelbeere)','Myrtille américaine (en corymbe)','Mirtillo gigante americano','Highbush blueberry','Arándano alto','beerenstrauch','1.2','2','1','1.5','mittel','4','aufrecht buschig, mehrtriebig','laubabwerfend','flachwurzler','0.4',NULL,'gering','sonnig','4','5.5','{sauer,humos,torfig,durchlässig}','hoch','4-7','-28',NULL,'1200','{3,4,10,11}','2.0','1.5','f','0','f','0.5','0.5','1','niedrig','keine',NULL,'gering','t','f','{"Vaccinium corymbosum (andere Sorte für besseren Ertrag)"}','t','Spätwinter (altes Holz auslichten)','Striktes Saurboden-Gewächs (pH 4-5,5) – Rhododendron-/Moorbeeterde, kein Kalk, kein hartes Leitungswasser (Regenwasser gießen). Flachwurzler gleichmäßig feucht halten, mulchen. Selbstfruchtbar, aber zweite Sorte erhöht Ertrag deutlich.','{"Kirschessigfliege (Drosophila suzukii)","Vögel (Netzschutz)","Chlorose bei zu hohem pH"}','In CH nur mit saurem Substrat erfolgreich – häufigster Fehler ist zu hoher Boden-pH. Bis ~1200 m. Essbar und sicher. Drosophila suzukii ist in CH verbreitetes Erntproblem.','Tox Info Suisse (tox.ch) – nicht giftig gelistet; Baumschul-Fachliteratur'),
('viburnum_lantana','Viburnum lantana','Wolliger Schneeball','Viorne lantane','Viburno lantana (Lantana)','Wayfaring tree','Barbadejo (lantana)','wildgehoelz','2','4','2','4','mittel','12','aufrecht, dicht, breit ausladend','laubabwerfend','herzwurzler','1.2',NULL,'gering','sonnig bis halbschattig','6.5','8','{kalkhaltig,lehmig,steinig,trocken}','gering bis mässig','5a','-29',NULL,'1500','{3,4,10,11}','2.0','1.5','f','0','t','2','1.5','1','mittel','leicht','unreife Früchte und Rinde leicht giftig (Magen-Darm-Beschwerden bei Verzehr roher unreifer Beeren); reife schwarze Beeren wenig problematisch aber ungeniessbar','gering','t','f',NULL,'t','nach der Blüte; verträgt Verjüngungsschnitt gut','Kalkliebend, trockenheitsverträglich - guter Hitzegehölz für trockene Standorte. Vogelnährgehölz. Filzig behaarte Blätter (daher ''wollig''). Leicht giftig - nicht ernste Gefahr, aber Beeren nicht verzehren.','{Schneeball-Blattkäfer,Blattläuse}','Heimisch (wärmeliebend, kalkreiche Böden Jura/Wallis), trockenheitsresistent - klimaangepasst.','tox.ch, InfoFlora, BAFU Wildgehölze, Baumschul-Fachliteratur')
